const lockMobileViewportZoom = () => {
  let lastTouchEndAt = 0;
  const blockGesture = (event) => event.preventDefault();
  ["gesturestart", "gesturechange", "gestureend"].forEach((eventName) => {
    document.addEventListener(eventName, blockGesture, { passive: false });
  });
  document.addEventListener(
    "touchmove",
    (event) => {
      if (event.touches && event.touches.length > 1) event.preventDefault();
    },
    { passive: false }
  );
  document.addEventListener(
    "touchend",
    (event) => {
      const target =
        event.target instanceof Element ? event.target : event.target?.parentElement;
      if (target?.closest("input, textarea, select")) return;
      const now = Date.now();
      if (now - lastTouchEndAt <= 300) event.preventDefault();
      lastTouchEndAt = now;
    },
    { passive: false }
  );
};

const aboutDateOrdinalSuffix = (day) => {
  const lastTwoDigits = day % 100;
  if (lastTwoDigits >= 11 && lastTwoDigits <= 13) return "th";
  if (day % 10 === 1) return "st";
  if (day % 10 === 2) return "nd";
  if (day % 10 === 3) return "rd";
  return "th";
};

const aboutDateLabel = (date) => {
  const weekday = date.toLocaleDateString("en-US", { weekday: "long" });
  const month = date.toLocaleDateString("en-US", { month: "long" });
  const day = date.getDate();
  return `${weekday} the ${day}${aboutDateOrdinalSuffix(day)}, ${month} ${date.getFullYear()}`;
};

const aboutDateValue = (date) =>
  [date.getFullYear(), date.getMonth() + 1, date.getDate()]
    .map((part, index) => (index ? String(part).padStart(2, "0") : String(part)))
    .join("-");

const updateAboutCurrentDate = (now = new Date()) => {
  if (!aboutCurrentDate) return;
  aboutCurrentDate.dateTime = aboutDateValue(now);
  aboutCurrentDate.textContent = aboutDateLabel(now);
};

const ABOUT_DEGREE_DWELL_MS = 1000;
const ABOUT_DEGREE_SCROLL_SPEED_PX_PER_SECOND = 30;
const ABOUT_DEGREE_MIN_TRAVEL_MS = 1200;
const aboutDegreeAnimations = new WeakMap();
const aboutDegreeTypes = [...document.querySelectorAll(".about-degree-type")];
const aboutDegreeFields = [...document.querySelectorAll("[data-about-degree-field]")];
const aboutDegreeReducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
let aboutDegreeRefreshFrame = 0;

const cancelAboutDegreeAnimation = (field) => {
  const animation = aboutDegreeAnimations.get(field);
  if (!animation) return;
  animation.cancel();
  aboutDegreeAnimations.delete(field);
};

const updateAboutDegreeTypeLabel = (type) => {
  const fullLabel = type.dataset.fullLabel || type.textContent;
  const shortLabel = type.dataset.shortLabel || fullLabel;
  type.textContent = fullLabel;
  if (type.clientWidth > 1 && type.scrollWidth > type.clientWidth + 1) {
    type.textContent = shortLabel;
  }
};

const updateAboutDegreeField = (field) => {
  const track = field.querySelector(".about-degree-field-track");
  cancelAboutDegreeAnimation(field);
  field.classList.remove("is-overflowing");
  field.tabIndex = -1;
  field.scrollLeft = 0;
  if (!track || field.clientWidth <= 1) return;

  const distance = Math.ceil(track.scrollWidth - field.clientWidth);
  if (distance <= 1) return;

  field.classList.add("is-overflowing");
  field.tabIndex = 0;
  if (
    aboutDegreeReducedMotion.matches ||
    document.activeElement === field ||
    typeof track.animate !== "function"
  ) {
    return;
  }

  const travelMs = Math.max(
    ABOUT_DEGREE_MIN_TRAVEL_MS,
    (distance / ABOUT_DEGREE_SCROLL_SPEED_PX_PER_SECOND) * 1000
  );
  const duration = 2 * (ABOUT_DEGREE_DWELL_MS + travelMs);
  const animation = track.animate(
    [
      { transform: "translateX(0px)", offset: 0 },
      {
        transform: "translateX(0px)",
        offset: ABOUT_DEGREE_DWELL_MS / duration,
      },
      {
        transform: `translateX(-${distance}px)`,
        offset: (ABOUT_DEGREE_DWELL_MS + travelMs) / duration,
      },
      {
        transform: `translateX(-${distance}px)`,
        offset: (2 * ABOUT_DEGREE_DWELL_MS + travelMs) / duration,
      },
      { transform: "translateX(0px)", offset: 1 },
    ],
    { duration, easing: "linear", iterations: Infinity }
  );
  aboutDegreeAnimations.set(field, animation);
};

const refreshAboutDegrees = () => {
  aboutDegreeRefreshFrame = 0;
  aboutDegreeTypes.forEach(updateAboutDegreeTypeLabel);
  aboutDegreeFields.forEach(updateAboutDegreeField);
};

const queueAboutDegreeRefresh = () => {
  if (aboutDegreeRefreshFrame) cancelAnimationFrame(aboutDegreeRefreshFrame);
  aboutDegreeRefreshFrame = requestAnimationFrame(refreshAboutDegrees);
};

aboutDegreeFields.forEach((field) => {
  field.addEventListener("focus", () => updateAboutDegreeField(field));
  field.addEventListener("blur", queueAboutDegreeRefresh);
  field.addEventListener("mouseenter", () => aboutDegreeAnimations.get(field)?.pause());
  field.addEventListener("mouseleave", () => aboutDegreeAnimations.get(field)?.play());
});

if (typeof ResizeObserver === "function") {
  const aboutDegreeResizeObserver = new ResizeObserver(queueAboutDegreeRefresh);
  [...aboutDegreeTypes, ...aboutDegreeFields].forEach((element) => {
    aboutDegreeResizeObserver.observe(element);
  });
} else {
  window.addEventListener("resize", queueAboutDegreeRefresh);
}
aboutDegreeReducedMotion.addEventListener("change", queueAboutDegreeRefresh);
document.fonts?.ready.then(queueAboutDegreeRefresh);
queueAboutDegreeRefresh();

const updateClock = () => {
  const now = new Date();
  clock.textContent = now.toLocaleTimeString([], {
    hour: "2-digit",
    minute: "2-digit",
  });
  updateAboutCurrentDate(now);
};

const updateCalendarClock = () => {
  if (!calendarClock || !calendarPopout.classList.contains("is-open")) return;
  const now = new Date();
  const hours = String(now.getHours()).padStart(2, "0");
  const minutes = String(now.getMinutes()).padStart(2, "0");
  const seconds = String(now.getSeconds()).padStart(2, "0");
  const blinkOn = Math.floor(Date.now() / 500) % 2 === 0;
  const colonClass = blinkOn ? "clock-colon" : "clock-colon is-off";
  calendarClock.innerHTML = `${hours}<span class="${colonClass}">:</span>${minutes}<span class="${colonClass}">:</span>${seconds}`;
  updateClockImage(now);
};

const updateClockImage = (now) => {
  if (!clockImage || !calendarPopout.classList.contains("is-open")) return;
  const hour = now.getHours();
  let src = "assets/night.png";
  let label = "Night scene";

  if (hour >= 5 && hour < 7) {
    src = "assets/sunrise.png";
    label = "Sunrise scene";
  } else if (hour >= 7 && hour < 18) {
    src = "assets/day.png";
    label = "Day scene";
  } else if (hour >= 18 && hour < 20) {
    src = "assets/sunset.png";
    label = "Sunset scene";
  }

  if (clockImage.getAttribute("src") !== src) {
    clockImage.setAttribute("src", src);
    clockImage.setAttribute("alt", label);
  }
};

let activateVisibleContent = (root) => {
  if (!isHomeActivationReady()) {
    runAfterHomeActivation(() => activateVisibleContent(root));
    return;
  }
  loadDeferredMedia(root, true);
};

const isWindowVisible = (win) =>
  Boolean(
    win &&
      !win.classList.contains("is-hidden") &&
      !win.classList.contains("is-closing")
  );

const pauseMediaPlayback = (root) => {
  if (!root) return;
  root.querySelectorAll("video, audio").forEach((media) => {
    media.pause();
  });
};

const isVisibleMediaElement = (media) =>
  Boolean(
    media &&
      !media.closest(".viewer-content.is-hidden") &&
      !media.closest('.window[data-media-closing="true"]') &&
      !media.closest(".app-window.is-hidden, .home-window.is-hidden")
  );

const playMediaElement = (media) => {
  if (!isHomeActivationReady()) {
    runAfterHomeActivation(() => playMediaElement(media));
    return;
  }
  if (!media || !isVisibleMediaElement(media)) return;
  if (!media.getAttribute("src") && media.dataset.src) {
    media.setAttribute("src", media.dataset.src);
    media.load();
  }
  const playRequest = media.play();
  if (playRequest && typeof playRequest.catch === "function") {
    playRequest.catch(() => {
      // Some browsers block autoplay unless it follows a user gesture.
    });
  }
};

const playActiveAutoplayVideos = (root) => {
  if (!root) return;
  const win = root.matches(".window") ? root : root.closest(".window");
  if (win && win.dataset.mediaClosing === "true") return;
  if (win && !isWindowVisible(win)) return;
  root.querySelectorAll("video[data-autoplay-on-active]").forEach(playMediaElement);
};

const stopMediaPlayback = (root) => {
  if (!root) return;

  root.querySelectorAll("video, audio").forEach((media) => {
    media.pause();
    if (!media.matches("[data-unload-on-hide]")) return;
    const src = media.getAttribute("src");
    if (src) media.dataset.src = src;
    media.removeAttribute("src");
    media.load();
  });

  root.querySelectorAll("iframe[data-unload-on-hide]").forEach((iframe) => {
    const src = iframe.getAttribute("src");
    if (src) iframe.dataset.src = src;
    iframe.removeAttribute("src");
  });
};

const selectWindowTab = (win, viewId) => {
  if (!win) return;
  const selectorButtons = win.querySelectorAll(".selector-item");
  const viewerPanels = win.querySelectorAll(".viewer-content");

  selectorButtons.forEach((button) => {
    button.classList.toggle("is-active", button.getAttribute("data-view") === viewId);
  });

  viewerPanels.forEach((panel) => {
    const isMatch = panel.getAttribute("data-view") === viewId;
    panel.classList.toggle("is-hidden", !isMatch);
    if (!isMatch) stopMediaPlayback(panel);
  });
};

const resetWindowToFirstTab = (win) => {
  if (!win) return;
  const firstButton = win.querySelector(".selector-item");
  if (firstButton) selectWindowTab(win, firstButton.getAttribute("data-view"));
};

const restartWindowAnimation = (win, animationClass) => {
  if (!win) return;
  win.classList.remove("is-opening", "is-closing");
  void win.offsetWidth;
  win.classList.add(animationClass);
};

