const getRelicRecoveryFitScale = () => {
  const scale = Number.parseFloat(
    relicRecoveryWindow?.style.getPropertyValue(RELIC_RECOVERY_FIT_SCALE_PROPERTY)
  );
  return Number.isFinite(scale) && scale > 0 ? Math.min(1, scale) : 1;
};

const getRandomEventVisualInsets = (win) => {
  if (win !== relicRecoveryWindow) {
    return { scale: 1, insetX: 0, insetY: 0 };
  }
  const scale = getRelicRecoveryFitScale();
  return {
    scale,
    insetX: (win.offsetWidth * (1 - scale)) / 2,
    insetY: (win.offsetHeight * (1 - scale)) / 2,
  };
};

const updateRelicRecoveryViewportFit = () => {
  if (
    !relicRecoveryWindow ||
    relicRecoveryWindow.classList.contains("is-hidden") ||
    relicRecoveryWindow.offsetWidth <= 0 ||
    relicRecoveryWindow.offsetHeight <= 0
  ) {
    return;
  }

  const previousInsets = getRandomEventVisualInsets(relicRecoveryWindow);
  const previousStyleLeft = Number.parseFloat(relicRecoveryWindow.style.left);
  const previousStyleTop = Number.parseFloat(relicRecoveryWindow.style.top);
  const preserveVisualPosition =
    relicRecoveryWindow.style.left.endsWith("px") &&
    relicRecoveryWindow.style.top.endsWith("px") &&
    Number.isFinite(previousStyleLeft) &&
    Number.isFinite(previousStyleTop);
  const previousVisualLeft = previousStyleLeft + previousInsets.insetX;
  const previousVisualTop = previousStyleTop + previousInsets.insetY;
  const availableWidth = Math.max(
    1,
    window.innerWidth - RANDOM_EVENT_VIEWPORT_PADDING * 2
  );
  const availableHeight = Math.max(
    1,
    window.innerHeight -
      RANDOM_EVENT_TASKBAR_CLEARANCE -
      RANDOM_EVENT_VIEWPORT_PADDING * 2
  );
  const fitScale = Math.min(
    1,
    availableWidth / relicRecoveryWindow.offsetWidth,
    availableHeight / relicRecoveryWindow.offsetHeight
  );
  relicRecoveryWindow.style.setProperty(
    RELIC_RECOVERY_FIT_SCALE_PROPERTY,
    String(fitScale)
  );

  if (!preserveVisualPosition) return;
  const nextInsets = getRandomEventVisualInsets(relicRecoveryWindow);
  relicRecoveryWindow.style.left = `${previousVisualLeft - nextInsets.insetX}px`;
  relicRecoveryWindow.style.top = `${previousVisualTop - nextInsets.insetY}px`;
};

const getRandomEventWindowBounds = (win) => {
  const rect = win.getBoundingClientRect();
  const { scale } = getRandomEventVisualInsets(win);
  const width =
    win === relicRecoveryWindow
      ? win.offsetWidth * scale
      : Math.max(win.offsetWidth, rect.width);
  const height =
    win === relicRecoveryWindow
      ? win.offsetHeight * scale
      : Math.max(win.offsetHeight, rect.height);
  const padding = RANDOM_EVENT_VIEWPORT_PADDING;
  return {
    width,
    height,
    padding,
    maxLeft: Math.max(padding, window.innerWidth - width - padding),
    maxTop: Math.max(
      padding,
      window.innerHeight - height - RANDOM_EVENT_TASKBAR_CLEARANCE
    ),
  };
};

const randomEventCandidateRect = (bounds, left, top) => ({
  left,
  top,
  right: left + bounds.width,
  bottom: top + bounds.height,
});

const randomEventPlacementObstacles = (win) =>
  Array.from(document.querySelectorAll(".window"))
    .filter((candidate) => {
      if (candidate === win) return false;
      if (candidate.closest(".window-explode-piece, .biden-explode-piece")) return false;
      if (candidate.hidden || candidate.classList.contains("is-hidden")) return false;
      if (candidate.getAttribute("aria-hidden") === "true") return false;
      return true;
    })
    .map((candidate) => candidate.getBoundingClientRect())
    .filter((rect) => rect.width > 0 && rect.height > 0);

const randomEventOverlapArea = (a, b, gap = 0) => {
  const overlapWidth = Math.max(
    0,
    Math.min(a.right, b.right + gap) - Math.max(a.left, b.left - gap)
  );
  const overlapHeight = Math.max(
    0,
    Math.min(a.bottom, b.bottom + gap) - Math.max(a.top, b.top - gap)
  );
  return overlapWidth * overlapHeight;
};

const scoreRandomEventPlacement = (candidate, obstacles) =>
  obstacles.reduce(
    (score, obstacle) =>
      score + randomEventOverlapArea(candidate, obstacle, RANDOM_EVENT_OBSTACLE_GAP),
    0
  );

const sampleRandomEventPosition = ({ padding, maxLeft, maxTop }) => ({
  left: padding + Math.random() * Math.max(0, maxLeft - padding),
  top: padding + Math.random() * Math.max(0, maxTop - padding),
});

const clampRandomEventPosition = ({ padding, maxLeft, maxTop }, { left, top }) => ({
  left: Math.max(padding, Math.min(left, maxLeft)),
  top: Math.max(padding, Math.min(top, maxTop)),
});

const findRandomEventOpenPosition = (win, preferredPositions = []) => {
  const bounds = getRandomEventWindowBounds(win);
  const obstacles = randomEventPlacementObstacles(win);
  const defaultPosition = sampleRandomEventPosition(bounds);

  if (!obstacles.length) {
    return clampRandomEventPosition(bounds, preferredPositions[0] || defaultPosition);
  }

  let bestPosition = null;
  let bestScore = Infinity;
  const cornerPositions = [
    { left: bounds.padding, top: bounds.padding },
    { left: bounds.maxLeft, top: bounds.padding },
    { left: bounds.padding, top: bounds.maxTop },
    { left: bounds.maxLeft, top: bounds.maxTop },
    {
      left: (bounds.padding + bounds.maxLeft) / 2,
      top: (bounds.padding + bounds.maxTop) / 2,
    },
  ];

  const considerPosition = (position) => {
    const clamped = clampRandomEventPosition(bounds, position);
    const rect = randomEventCandidateRect(bounds, clamped.left, clamped.top);
    const score = scoreRandomEventPlacement(rect, obstacles);

    if (score < bestScore) {
      bestScore = score;
      bestPosition = clamped;
    }

    return score === 0;
  };

  const seededPositions = [...preferredPositions];
  for (const position of seededPositions) {
    if (considerPosition(position)) return bestPosition;
  }

  for (let attempt = 0; attempt < RANDOM_EVENT_PLACEMENT_ATTEMPTS; attempt += 1) {
    if (considerPosition(sampleRandomEventPosition(bounds))) return bestPosition;
  }

  for (const position of cornerPositions) {
    if (considerPosition(position)) return bestPosition;
  }

  return bestPosition || defaultPosition;
};

const setRandomEventWindowPosition = (win, left, top, { onPosition } = {}) => {
  if (!win) return;
  const { padding, maxLeft, maxTop } = getRandomEventWindowBounds(win);
  const nextLeft = Math.round(Math.max(padding, Math.min(left, maxLeft)));
  const nextTop = Math.round(Math.max(padding, Math.min(top, maxTop)));
  const { insetX, insetY } = getRandomEventVisualInsets(win);
  win.style.translate = "0 0";
  win.style.left = `${nextLeft - insetX}px`;
  win.style.top = `${nextTop - insetY}px`;
  if (onPosition) onPosition(nextLeft, nextTop);
};

const positionRandomEventWindowInViewport = (win, options) => {
  if (!win) return;
  const { left, top } = findRandomEventOpenPosition(win);
  setRandomEventWindowPosition(win, left, top, options);
};

const clampRandomEventWindowToViewport = (win, options) => {
  if (!win || win.classList.contains("is-hidden")) return;
  const rect = win.getBoundingClientRect();
  const styleLeft = Number.parseFloat(win.style.left);
  const styleTop = Number.parseFloat(win.style.top);
  const { insetX, insetY } = getRandomEventVisualInsets(win);
  const currentLeft = Number.isFinite(styleLeft) ? styleLeft + insetX : rect.left;
  const currentTop = Number.isFinite(styleTop) ? styleTop + insetY : rect.top;
  setRandomEventWindowPosition(win, currentLeft, currentTop, options);
};

const clampRandomEventWindowAfterMediaLoad = (win, options) => {
  if (!win) return;
  requestAnimationFrame(() => clampRandomEventWindowToViewport(win, options));
  [80, 240, 360].forEach((delay) => {
    setTimeout(() => clampRandomEventWindowToViewport(win, options), delay);
  });
  win.querySelectorAll("img").forEach((image) => {
    if (image.complete && image.naturalWidth > 0) {
      clampRandomEventWindowToViewport(win, options);
      return;
    }
    image.addEventListener(
      "load",
      () => clampRandomEventWindowToViewport(win, options),
      { once: true }
    );
  });
};

const clampVisibleRandomEventWindows = () => {
  randomEventViewportWindows().forEach((win) => clampRandomEventWindowToViewport(win));
};

const watchRandomEventViewportMedia = () => {
  randomEventViewportWindows().forEach((win) => {
    win.querySelectorAll("img").forEach((image) => {
      image.addEventListener("load", () => clampRandomEventWindowToViewport(win));
    });
  });
};

const unloadDeferredImages = (root) => {
  if (!root) return;
  root.querySelectorAll("img[data-src]").forEach((image) => {
    image.removeAttribute("src");
  });
};

const isManagedRandomEventWindowVisible = (win) =>
  Boolean(
    win &&
      !win.classList.contains("is-hidden") &&
      win.getAttribute("aria-hidden") === "false"
  );

const showManagedRandomEventWindow = (
  win,
  { beforeShow, clampAfterMediaLoad = false } = {}
) => {
  if (!win) return false;
  if (isManagedRandomEventWindowVisible(win)) {
    win.style.zIndex = String(topZ++);
    return false;
  }

  if (beforeShow) beforeShow();
  loadDeferredMedia(win);
  win.classList.remove("is-hidden", "is-closing");
  win.setAttribute("aria-hidden", "false");
  positionRandomEventWindowInViewport(win);
  win.style.zIndex = String(topZ++);
  restartWindowAnimation(win, "is-opening");
  if (clampAfterMediaLoad) clampRandomEventWindowAfterMediaLoad(win);
  return true;
};

const closeManagedRandomEventWindow = (win) => {
  if (!win || win.classList.contains("is-hidden")) return;
  win.setAttribute("aria-hidden", "true");
  restartWindowAnimation(win, "is-closing");
};

const bindManagedRandomEventWindowAnimation = (
  win,
  { afterClose, unloadImages = true } = {}
) => {
  if (!win) return;

  win.addEventListener("click", (event) => {
    event.stopPropagation();
  });

  win.addEventListener("animationend", (event) => {
    if (event.target !== win) return;
    if (event.animationName === "retro-window-open") {
      win.classList.remove("is-opening");
      return;
    }
    if (event.animationName === "retro-window-close") {
      win.classList.remove("is-closing");
      win.classList.add("is-hidden");
      if (afterClose) afterClose();
      if (unloadImages) unloadDeferredImages(win);
    }
  });
};

const bindRandomEventButton = (button, action) => {
  if (!button) return;
  button.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    action(event);
  });
};

const isDebugSystemAlertVisible = () =>
  isManagedRandomEventWindowVisible(debugSystemAlertWindow);

const debugSystemAlertReducedMotionQuery =
  typeof window.matchMedia === "function"
    ? window.matchMedia("(prefers-reduced-motion: reduce)")
    : null;

const resetDebugSystemAlert = () => {
  debugSystemAlertActiveId = "";
  if (debugSystemAlertWindow) delete debugSystemAlertWindow.dataset.alertId;
  const focusTarget = debugSystemAlertFocusReturn;
  debugSystemAlertFocusReturn = null;
  if (
    focusTarget?.isConnected &&
    !focusTarget.closest("[inert]") &&
    typeof focusTarget.focus === "function"
  ) {
    focusTarget.focus({ preventScroll: true });
  }
  if (debugSystemAlertWindow?.contains(document.activeElement)) {
    document.activeElement.blur();
  }
};

const renderDebugSystemAlert = (
  alert,
  {
    root = debugSystemAlertWindow,
    interactive = root === debugSystemAlertWindow,
  } = {}
) => {
  if (!alert || !root) return [];
  const title = root.querySelector("#debug-system-alert-title");
  const icon = root.querySelector("#debug-system-alert-icon");
  const message = root.querySelector("#debug-system-alert-message");
  const actions = root.querySelector("#debug-system-alert-actions");
  if (title) title.textContent = alert.title;
  if (icon) icon.src = alert.icon;
  if (message) message.textContent = alert.body;
  if (!actions) return [];

  actions.dataset.buttonAlignment = alert.buttonAlignment;
  const buttons = alert.buttons.map((buttonDefinition) => {
    const button = actions.ownerDocument.createElement("button");
    button.type = "button";
    button.className = "debug-system-alert-action";
    button.dataset.systemAlertButtonId = buttonDefinition.id;
    button.dataset.systemAlertAction = buttonDefinition.action;
    button.textContent = buttonDefinition.label;
    if (interactive && buttonDefinition.action === "dismiss") {
      bindRandomEventButton(button, closeDebugSystemAlert);
    }
    return button;
  });
  actions.replaceChildren(...buttons);
  root.dataset.alertId = alert.id;
  return buttons;
};

const showDebugSystemAlert = (alert) => {
  if (!alert) return false;

  const focusReturn =
    document.activeElement instanceof HTMLElement ? document.activeElement : null;
  let actionButtons = [];
  const didOpen = showManagedRandomEventWindow(debugSystemAlertWindow, {
    beforeShow: () => {
      actionButtons = renderDebugSystemAlert(alert);
    },
    clampAfterMediaLoad: true,
  });
  if (!didOpen) return false;

  debugSystemAlertActiveId = alert.id;
  debugSystemAlertFocusReturn = focusReturn;
  if (debugSystemAlertReducedMotionQuery?.matches) {
    debugSystemAlertWindow.classList.remove("is-opening");
  }
  requestAnimationFrame(() => actionButtons[0]?.focus({ preventScroll: true }));
  return true;
};

const closeDebugSystemAlert = () => {
  closeManagedRandomEventWindow(debugSystemAlertWindow);
  if (!debugSystemAlertReducedMotionQuery?.matches || !debugSystemAlertWindow) return;
  debugSystemAlertWindow.classList.remove("is-closing");
  debugSystemAlertWindow.classList.add("is-hidden");
  resetDebugSystemAlert();
};

const isNekoStreamAlertVisible = () =>
  isManagedRandomEventWindowVisible(nekoStreamAlertWindow);

const nekoStreamAlertReducedMotionQuery =
  typeof window.matchMedia === "function"
    ? window.matchMedia("(prefers-reduced-motion: reduce)")
    : null;

const prefersReducedNekoStreamAlertMotion = () =>
  Boolean(nekoStreamAlertReducedMotionQuery?.matches);

const setNekoStreamAlertIconFrame = () => {
  if (!nekoStreamAlertIcon) return;
  const sprite = nekoStreamAlertIconFrame % 2 === 0
    ? NEKO_SPRITES.sleep1
    : NEKO_SPRITES.sleep2;
  if (nekoStreamAlertIcon.getAttribute("src") !== sprite) {
    nekoStreamAlertIcon.src = sprite;
  }
};

const stopNekoStreamAlertIconAnimation = () => {
  if (nekoStreamAlertIconTimerId !== null) {
    window.clearInterval(nekoStreamAlertIconTimerId);
  }
  nekoStreamAlertIconTimerId = null;
};

const restoreNekoStreamAlertFocus = () => {
  const focusTarget = nekoStreamAlertFocusReturn;
  nekoStreamAlertFocusReturn = null;
  if (
    focusTarget?.isConnected &&
    !focusTarget.closest("[inert]") &&
    typeof focusTarget.focus === "function"
  ) {
    focusTarget.focus({ preventScroll: true });
  }
  if (nekoStreamAlertWindow?.contains(document.activeElement)) {
    document.activeElement.blur();
  }
};

const startNekoStreamAlertIconAnimation = () => {
  stopNekoStreamAlertIconAnimation();
  nekoStreamAlertIconFrame = 0;
  setNekoStreamAlertIconFrame();
  if (prefersReducedNekoStreamAlertMotion()) return;
  nekoStreamAlertIconTimerId = window.setInterval(() => {
    if (!isNekoStreamAlertVisible()) {
      stopNekoStreamAlertIconAnimation();
      return;
    }
    nekoStreamAlertIconFrame += 1;
    setNekoStreamAlertIconFrame();
  }, NEKO_SLEEP_FRAME_INTERVAL_MS);
};

const resetNekoStreamAlert = () => {
  stopNekoStreamAlertIconAnimation();
  nekoStreamAlertResponsePending = false;
  restoreNekoStreamAlertFocus();
};

const handleNekoStreamAlertMotionPreferenceChange = () => {
  if (!prefersReducedNekoStreamAlertMotion()) {
    if (isNekoStreamAlertVisible() && nekoStreamAlertResponsePending) {
      startNekoStreamAlertIconAnimation();
    }
    return;
  }

  stopNekoStreamAlertIconAnimation();
  nekoStreamAlertIconFrame = 0;
  setNekoStreamAlertIconFrame();
  if (!nekoStreamAlertWindow) return;

  const wasClosing = nekoStreamAlertWindow.classList.contains("is-closing");
  nekoStreamAlertWindow.classList.remove("is-opening");
  if (!wasClosing) return;
  nekoStreamAlertWindow.classList.remove("is-closing");
  nekoStreamAlertWindow.classList.add("is-hidden");
  resetNekoStreamAlert();
};

const showNekoStreamAlert = () => {
  const focusReturn =
    document.activeElement instanceof HTMLElement ? document.activeElement : null;
  const didOpen = showManagedRandomEventWindow(nekoStreamAlertWindow, {
    beforeShow: () => {
      stopNekoStreamAlertIconAnimation();
      nekoStreamAlertIconFrame = 0;
      setNekoStreamAlertIconFrame();
    },
    clampAfterMediaLoad: true,
  });
  if (!didOpen) return false;

  nekoStreamAlertFocusReturn = focusReturn;
  nekoStreamAlertResponsePending = true;
  startNekoStreamAlertIconAnimation();
  if (prefersReducedNekoStreamAlertMotion()) {
    nekoStreamAlertWindow.classList.remove("is-opening");
  }
  requestAnimationFrame(() => nekoStreamAlertYes?.focus({ preventScroll: true }));
  return true;
};

const respondToNekoStreamAlert = (shouldStartStream) => {
  if (!nekoStreamAlertResponsePending || !isNekoStreamAlertVisible()) return false;
  nekoStreamAlertResponsePending = false;
  stopNekoStreamAlertIconAnimation();
  restoreNekoStreamAlertFocus();
  closeManagedRandomEventWindow(nekoStreamAlertWindow);
  if (prefersReducedNekoStreamAlertMotion()) {
    nekoStreamAlertWindow.classList.remove("is-opening", "is-closing");
    nekoStreamAlertWindow.classList.add("is-hidden");
    resetNekoStreamAlert();
  }
  if (shouldStartStream) startNekoStream();
  return true;
};

