const triggerSpellStackCounterFlash = () => {
  const flash = document.createElement("div");
  flash.className = "spell-stack-counter-flash";
  document.body.appendChild(flash);
  const animation = flash.animate(
    [
      { opacity: 0 },
      { opacity: 0.88, offset: 0.12 },
      { opacity: 0.72, offset: 0.36 },
      { opacity: 0 },
    ],
    {
      duration: 620,
      easing: "ease-out",
      fill: "forwards",
    }
  );
  animation.addEventListener("finish", () => flash.remove(), { once: true });
};

const counterSpellOnStack = () => {
  if (!spellStackWindow || spellStackWindow.classList.contains("is-hidden")) return;
  clearSpellStackLightning();
  triggerSpellStackCounterFlash();
  closeManagedRandomEventWindow(spellStackWindow);
};

const triggerSpellStackLightning = () => {
  if (!spellStackWindow || !spellStackLightningCanvas) return;
  clearSpellStackLightning();
  spellStackWindow.classList.add("is-spell-hit");
  const startedAt = performance.now();
  const duration = 900;

  const render = (now) => {
    const progress = Math.min(1, (now - startedAt) / duration);
    const alpha = Math.max(0, 1 - progress * 0.55);
    drawLightningBorderFrame(spellStackLightningCanvas, alpha, RED_LIGHTNING_PALETTE);
    if (progress < 1) {
      spellStackLightningFrame = requestAnimationFrame(render);
      return;
    }
    clearSpellStackLightning();
  };

  spellStackLightningFrame = requestAnimationFrame(render);
  spellStackLightningTimer = window.setTimeout(clearSpellStackLightning, duration + 80);
};

const refuseSpellOnStackCounter = () => {
  if (!spellStackWindow || spellStackWindow.classList.contains("is-hidden")) return;
  triggerSpellStackLightning();
  closeManagedRandomEventWindow(spellStackWindow);
};

const SOOT_SPRITES_DESKTOP_COUNT = 32;
const SOOT_SPRITES_MOBILE_COUNT = 20;
const SOOT_SPRITES_CLEANUP_MS = 27000;
const SOOT_SPRITES_REVEAL_DELAY_MS = 120;
const SOOT_SPRITES_WINDOW_HOLD_AFTER_LOAD_MS = 1000;
const SOOT_SPRITES_SPAWN_CLEARANCE = 64;
const SOOT_SPRITES_FALL_SAMPLE_COUNT = 12;
const SOOT_SPRITES_DIRECTION_SWITCH_CHANCE = 0.55;
const SOOT_SPRITES_DIRECTION_SWITCH_MIN_DELAY_MS = 1000;
const SOOT_SPRITES_DIRECTION_SWITCH_MAX_DELAY_MS = 3000;
const SOOT_SPRITES_MIN_PATH_SPEED = 0.22;
const SOOT_SPRITES_AIR_TRAIL_CANDIES_PER_SPRITE = 2.2;
const SOOT_SPRITES_GROUND_RUN_CANDY_MULTIPLIER = 2;
const SOOT_CANDY_LANDING_PROGRESS = 0.72;
const SOOT_CANDY_HOLD_AFTER_LANDING_MS = 4000;
const SOOT_CANDY_FADE_DURATION_MS = 1200;
const SOOT_SPRITES_CANDY_COLORS = Object.freeze([
  "#c9f7c2",
  "#ffc6dc",
  "#fff2a6",
  "#fffaf0",
  "#bde7ff",
]);

const isSootSpritesVisible = () =>
  isManagedRandomEventWindowVisible(sootSpritesWindow) ||
  Boolean(
    sootSpritesOverlay ||
      sootSpritesRevealTimer ||
      sootSpritesWindowHoldTimer
  );

const randomSootSpriteValue = (min, max) => min + Math.random() * (max - min);

const randomSootCandyColor = () =>
  SOOT_SPRITES_CANDY_COLORS[
    Math.floor(Math.random() * SOOT_SPRITES_CANDY_COLORS.length)
  ];

const setSootSpritePx = (element, property, value) => {
  element.style.setProperty(property, `${Math.round(value)}px`);
};

const clearSootSpritesLifecycleTimers = () => {
  if (sootSpritesRevealTimer) window.clearTimeout(sootSpritesRevealTimer);
  if (sootSpritesWindowHoldTimer) window.clearTimeout(sootSpritesWindowHoldTimer);
  sootSpritesRevealTimer = null;
  sootSpritesWindowHoldTimer = null;
};

const cleanupSootSpritesOverlay = () => {
  clearSootSpritesLifecycleTimers();
  if (sootSpritesOverlay) {
    sootSpritesOverlay.remove();
    sootSpritesOverlay = null;
  }
  if (sootSpritesCleanupTimer) {
    window.clearTimeout(sootSpritesCleanupTimer);
    sootSpritesCleanupTimer = null;
  }
  document.body.classList.remove("is-soot-sprites-active");
};

const setSootSpritesWindowLoading = (loading) => {
  sootSpritesWindow?.classList.toggle("is-loading-sprites", loading);
  [sootSpritesYes, sootSpritesNo].forEach((button) => {
    if (!button) return;
    button.disabled = loading;
    button.setAttribute("aria-disabled", String(loading));
  });
};

const getSootSpritesLaunchRect = () => {
  const rect = sootSpritesWindow?.getBoundingClientRect();
  if (rect && rect.width > 0 && rect.height > 0) return rect;
  const width = Math.min(340, window.innerWidth - 32);
  const height = 150;
  return {
    left: (window.innerWidth - width) / 2,
    top: Math.max(16, (window.innerHeight - height) / 2),
    width,
    height,
  };
};

const getSootSpritesStagedZIndex = () => {
  const windowZIndex = Number.parseInt(sootSpritesWindow?.style.zIndex || "", 10);
  return Math.max(0, (Number.isFinite(windowZIndex) ? windowZIndex : 140) - 1);
};

const reserveSootSpritesSpawnLane = () => {
  if (!sootSpritesWindow) return;
  const toolbarTop = getSootSpritesToolbarTop();
  const currentLeft = Number.parseFloat(sootSpritesWindow.style.left);
  const currentTop = Number.parseFloat(sootSpritesWindow.style.top);
  const maxTop = Math.max(
    12,
    toolbarTop - sootSpritesWindow.offsetHeight - SOOT_SPRITES_SPAWN_CLEARANCE
  );
  setRandomEventWindowPosition(
    sootSpritesWindow,
    Number.isFinite(currentLeft) ? currentLeft : 12,
    Math.min(Number.isFinite(currentTop) ? currentTop : maxTop, maxTop)
  );
};

const getSootSpritesToolbarTop = () => {
  const appMenu = document.querySelector(".taskbar-apps");
  const taskbar = appMenu || document.querySelector(".taskbar");
  return taskbar?.getBoundingClientRect().top || window.innerHeight - 52;
};

const getSootSpritesGroundY = (spriteSize) => {
  const toolbarTop = getSootSpritesToolbarTop();
  return Math.max(
    0,
    Math.min(window.innerHeight - spriteSize, toolbarTop - spriteSize)
  );
};

const getSootCandyLandingY = (candySize) => {
  const toolbarTop = getSootSpritesToolbarTop();
  return Math.max(
    0,
    Math.min(window.innerHeight - candySize, toolbarTop - candySize)
  );
};

const getSootSpriteParabolaPoint = (trajectory, progress) => {
  const clampedProgress = Math.min(1, Math.max(0, progress));
  return {
    x: trajectory.startX + (trajectory.landingX - trajectory.startX) * clampedProgress,
    y:
      trajectory.startY +
      (trajectory.groundY - trajectory.startY) * clampedProgress * clampedProgress,
  };
};

const createSootSpriteFallSamples = (trajectory) => {
  let previousPoint = getSootSpriteParabolaPoint(trajectory, 0);
  let distance = 0;
  const samples = [
    {
      ...previousPoint,
      distance,
      progress: 0,
    },
  ];

  for (let index = 1; index <= SOOT_SPRITES_FALL_SAMPLE_COUNT; index += 1) {
    const progress = index / SOOT_SPRITES_FALL_SAMPLE_COUNT;
    const point = getSootSpriteParabolaPoint(trajectory, progress);
    distance += Math.hypot(point.x - previousPoint.x, point.y - previousPoint.y);
    samples.push({
      ...point,
      distance,
      progress,
    });
    previousPoint = point;
  }

  return samples;
};

const getSootSpriteFallPointAtDistance = (trajectory, distance) => {
  const samples = trajectory.fallSamples;
  if (!samples?.length) return getSootSpriteParabolaPoint(trajectory, 0);
  if (distance <= 0) return samples[0];

  for (let index = 1; index < samples.length; index += 1) {
    const previousSample = samples[index - 1];
    const nextSample = samples[index];
    if (distance > nextSample.distance) continue;

    const span = nextSample.distance - previousSample.distance || 1;
    const segmentProgress = (distance - previousSample.distance) / span;
    return {
      distance,
      progress:
        previousSample.progress +
        (nextSample.progress - previousSample.progress) * segmentProgress,
      x: previousSample.x + (nextSample.x - previousSample.x) * segmentProgress,
      y: previousSample.y + (nextSample.y - previousSample.y) * segmentProgress,
    };
  }

  return samples[samples.length - 1];
};

const getSootSpriteFallScale = (pathProgress, runScale) => {
  const progress = Math.min(1, Math.max(0, pathProgress));
  const baseScale = 1 + (runScale - 1) * progress;
  const arcStretch = Math.sin(progress * Math.PI) * 0.04;
  return Number((baseScale + arcStretch).toFixed(3));
};

const getSootSpriteTransform = (point, scale) =>
  `translate3d(${point.x.toFixed(1)}px, ${point.y.toFixed(1)}px, 0) scale(${scale})`;

const getSootSpriteTimelineOffset = (trajectory, distance) => {
  if (!trajectory.duration || !trajectory.pathSpeed) return 0;
  if (distance <= trajectory.fallLength) {
    return Math.min(1, Math.max(0, distance / trajectory.pathSpeed / trajectory.duration));
  }

  const segment =
    trajectory.runSegments.find((candidate) => distance <= candidate.endDistance) ||
    trajectory.runSegments[trajectory.runSegments.length - 1];
  if (!segment) return 1;

  const elapsedTime =
    segment.startTime +
    (distance - segment.startDistance) / Math.max(0.001, segment.speed);
  return Math.min(1, Math.max(0, elapsedTime / trajectory.duration));
};

const createSootSpritePathKeyframes = (trajectory) => [
  ...trajectory.fallSamples.map((sample) => ({
    offset: getSootSpriteTimelineOffset(trajectory, sample.distance),
    opacity: 1,
    transform: getSootSpriteTransform(
      sample,
      getSootSpriteFallScale(sample.progress, trajectory.runScale)
    ),
  })),
  ...trajectory.runSegments.map((segment) => ({
    offset: Math.min(1, Math.max(0, segment.endTime / trajectory.duration)),
    opacity: 1,
    transform: getSootSpriteTransform(
      { x: segment.endX, y: trajectory.exitY },
      trajectory.runScale
    ),
  })),
];

const animateSootSpriteElement = (sprite, trajectory) => {
  if (typeof sprite.animate !== "function") return null;
  sprite.classList.add("soot-sprite--scripted");
  return sprite.animate(createSootSpritePathKeyframes(trajectory), {
    delay: trajectory.delay,
    duration: trajectory.duration,
    easing: "linear",
    fill: "both",
  });
};

const getSootCandyGravityPoint = (trajectory, progress) => {
  const clampedProgress = Math.min(1, Math.max(0, progress));
  return {
    x:
      trajectory.startX +
      (trajectory.landingX - trajectory.startX) * clampedProgress,
    y:
      trajectory.startY +
      (trajectory.landingY - trajectory.startY) * clampedProgress * clampedProgress,
  };
};

const createSootCandyTrajectory = ({
  startX,
  startY,
  size,
  minHorizontalTravel,
  maxHorizontalTravel,
}) => {
  const landingY = getSootCandyLandingY(size);
  const safeStartX = Math.max(
    6,
    Math.min(window.innerWidth - size - 6, startX)
  );
  const safeStartY = Math.max(
    0,
    Math.min(startY, landingY - randomSootSpriteValue(18, 72))
  );
  const landingDirection = Math.random() < 0.5 ? -1 : 1;
  const landingX = Math.max(
    6,
    Math.min(
      window.innerWidth - size - 6,
      safeStartX +
        landingDirection *
          randomSootSpriteValue(minHorizontalTravel, maxHorizontalTravel)
    )
  );
  const trajectory = {
    startX: safeStartX,
    startY: safeStartY,
    landingX,
    landingY,
  };
  const fallQuarter = getSootCandyGravityPoint(trajectory, 0.25);
  const fallMidpoint = getSootCandyGravityPoint(trajectory, 0.5);
  const fallThreeQuarter = getSootCandyGravityPoint(trajectory, 0.75);

  return {
    ...trajectory,
    fallQuarterX: fallQuarter.x,
    fallQuarterY: fallQuarter.y,
    fallMidpointX: fallMidpoint.x,
    fallMidpointY: fallMidpoint.y,
    fallThreeQuarterX: fallThreeQuarter.x,
    fallThreeQuarterY: fallThreeQuarter.y,
  };
};

const setSootCandyTrajectoryProperties = (candy, trajectory) => {
  setSootSpritePx(candy, "--candy-x0", trajectory.startX);
  setSootSpritePx(candy, "--candy-y0", trajectory.startY);
  setSootSpritePx(candy, "--candy-x-fall-25", trajectory.fallQuarterX);
  setSootSpritePx(candy, "--candy-y-fall-25", trajectory.fallQuarterY);
  setSootSpritePx(candy, "--candy-x-fall-50", trajectory.fallMidpointX);
  setSootSpritePx(candy, "--candy-y-fall-50", trajectory.fallMidpointY);
  setSootSpritePx(candy, "--candy-x-fall-75", trajectory.fallThreeQuarterX);
  setSootSpritePx(candy, "--candy-y-fall-75", trajectory.fallThreeQuarterY);
  setSootSpritePx(candy, "--candy-x-land", trajectory.landingX);
  setSootSpritePx(candy, "--candy-y-land", trajectory.landingY);
};

const setSootCandySpinProperties = (candy, spin) => {
  candy.style.setProperty("--candy-spin-25", `${(spin * 0.25).toFixed(0)}deg`);
  candy.style.setProperty("--candy-spin-50", `${(spin * 0.5).toFixed(0)}deg`);
  candy.style.setProperty("--candy-spin-75", `${(spin * 0.75).toFixed(0)}deg`);
  candy.style.setProperty("--candy-spin", `${spin.toFixed(0)}deg`);
};

const setSootCandyTimingProperties = (candy, { delay, fallDuration }) => {
  const landingDelay =
    delay + fallDuration * SOOT_CANDY_LANDING_PROGRESS;
  const fadeDelay = landingDelay + SOOT_CANDY_HOLD_AFTER_LANDING_MS;

  candy.style.setProperty("--candy-delay", `${delay}ms`);
  candy.style.setProperty("--candy-fall-duration", `${fallDuration}ms`);
  candy.style.setProperty(
    "--candy-hold-duration",
    `${SOOT_CANDY_HOLD_AFTER_LANDING_MS}ms`
  );
  candy.style.setProperty(
    "--candy-fade-duration",
    `${SOOT_CANDY_FADE_DURATION_MS}ms`
  );
  candy.style.setProperty("--candy-fade-delay", `${fadeDelay}ms`);
};

const getSootSpriteRunExitX = (size, direction) =>
  direction < 0
    ? -size - randomSootSpriteValue(60, 190)
    : window.innerWidth + randomSootSpriteValue(60, 190);

const isSootSpriteOnScreenAtX = (x, size) => x + size > 0 && x < window.innerWidth;

const createSootSpriteRunSegment = ({
  startX,
  endX,
  startDistance,
  groundY,
}) => {
  const length = Math.max(1, Math.hypot(endX - startX, 0));
  return {
    startDistance,
    endDistance: startDistance + length,
    startX,
    endX,
    y: groundY,
    length,
  };
};

const applySootSpriteRunSegmentTiming = ({
  fallLength,
  pathSpeed,
  runSegments,
  switchSpeedMultiplier,
}) => {
  let elapsedTime = fallLength / pathSpeed;
  return runSegments.map((segment, index) => {
    const speedMultiplier = index === 0 ? 1 : switchSpeedMultiplier;
    const speed = pathSpeed * speedMultiplier;
    const duration = segment.length / speed;
    const timedSegment = {
      ...segment,
      duration,
      endTime: elapsedTime + duration,
      speed,
      speedMultiplier,
      startTime: elapsedTime,
    };
    elapsedTime = timedSegment.endTime;
    return timedSegment;
  });
};

const createSootSpriteSpawnGrid = (launchRect, spriteCount) => {
  const aspectRatio = launchRect.width / Math.max(1, launchRect.height);
  const columns = Math.max(
    1,
    Math.min(spriteCount, Math.round(Math.sqrt(spriteCount * aspectRatio)))
  );
  const rows = Math.ceil(spriteCount / columns);
  const horizontalInset = Math.min(20, Math.max(8, launchRect.width * 0.08));
  const verticalInset = Math.min(20, Math.max(8, launchRect.height * 0.1));
  const usableWidth = Math.max(1, launchRect.width - horizontalInset * 2);
  const usableHeight = Math.max(1, launchRect.height - verticalInset * 2);

  return Array.from({ length: spriteCount }, (_, index) => {
    const row = Math.floor(index / columns);
    const column = index % columns;
    const spritesInRow = Math.min(columns, spriteCount - row * columns);
    return {
      x:
        launchRect.left +
        horizontalInset +
        (usableWidth * (column + 0.5)) / spritesInRow,
      y:
        launchRect.top +
        verticalInset +
        (usableHeight * (row + 0.5)) / rows,
    };
  });
};

const createSootSpriteTrajectory = (launchRect, { startPoint } = {}) => {
  const size = Math.round(randomSootSpriteValue(24, 40));
  const groundY = getSootSpritesGroundY(size);
  const minimumFallDistance = Math.min(24, size);
  const startMinX = launchRect.left + 4;
  const startMaxX = Math.max(startMinX, launchRect.left + launchRect.width - size - 4);
  const startMinY = launchRect.top + 4;
  const startMaxY = Math.max(
    startMinY,
    Math.min(launchRect.top + launchRect.height - size - 4, groundY - minimumFallDistance)
  );
  const startX = startPoint
    ? Math.max(startMinX, Math.min(startMaxX, startPoint.x - size / 2))
    : randomSootSpriteValue(startMinX, startMaxX);
  const startY = startPoint
    ? Math.max(startMinY, Math.min(startMaxY, startPoint.y - size / 2))
    : randomSootSpriteValue(startMinY, startMaxY);
  const minLandingX = 10;
  const maxLandingX = Math.max(minLandingX, window.innerWidth - size - 10);
  const leftTravel = Math.max(0, startX - minLandingX);
  const rightTravel = Math.max(0, maxLandingX - startX);
  let fallSide = Math.random() < 0.5 ? -1 : 1;
  if ((fallSide < 0 ? leftTravel : rightTravel) < 80) {
    fallSide = leftTravel > rightTravel ? -1 : 1;
  }
  const availableFallTravel = fallSide < 0 ? leftTravel : rightTravel;
  const maxFallTravel = Math.min(availableFallTravel, randomSootSpriteValue(190, 380));
  const minFallTravel = Math.min(maxFallTravel, 72);
  const fallTravel =
    maxFallTravel <= 0 ? 0 : randomSootSpriteValue(minFallTravel, maxFallTravel);
  const landingX = startX + fallSide * fallTravel;
  const initialRunDirection = Math.random() < 0.5 ? -1 : 1;
  const initialExitX = getSootSpriteRunExitX(size, initialRunDirection);
  const exitY = groundY;
  const delay = 0;
  const baseDuration = randomSootSpriteValue(3600, 4800);
  const runScale = randomSootSpriteValue(0.78, 1.08);
  const directionSwitchDelay = randomSootSpriteValue(
    SOOT_SPRITES_DIRECTION_SWITCH_MIN_DELAY_MS,
    SOOT_SPRITES_DIRECTION_SWITCH_MAX_DELAY_MS
  );
  const directionSwitchRoll = Math.random();
  const trajectory = {
    size,
    startX,
    startY,
    groundY,
    landingX,
    exitX: initialExitX,
    exitY,
    delay,
    duration: baseDuration,
    initialRunDirection,
    runScale,
  };
  const fallSamples = createSootSpriteFallSamples(trajectory);
  const fallLength = fallSamples[fallSamples.length - 1].distance;
  const initialRunSegment = createSootSpriteRunSegment({
    startX: landingX,
    endX: initialExitX,
    startDistance: fallLength,
    groundY,
  });
  const basePathLength = Math.max(1, fallLength + initialRunSegment.length);
  const pathSpeed = Math.max(SOOT_SPRITES_MIN_PATH_SPEED, basePathLength / baseDuration);
  const switchRunDistance = pathSpeed * directionSwitchDelay;
  const switchX = landingX + initialRunDirection * switchRunDistance;
  const shouldSwitchDirection =
    directionSwitchRoll < SOOT_SPRITES_DIRECTION_SWITCH_CHANCE &&
    switchRunDistance < initialRunSegment.length &&
    isSootSpriteOnScreenAtX(switchX, size);
  const directionSwitchSpeedMultiplier = shouldSwitchDirection
    ? randomSootSpriteValue(1, 2)
    : 1;
  const runSegments = shouldSwitchDirection
    ? [
        createSootSpriteRunSegment({
          startX: landingX,
          endX: switchX,
          startDistance: fallLength,
          groundY,
        }),
      ]
    : [initialRunSegment];

  if (shouldSwitchDirection) {
    const switchedExitX = getSootSpriteRunExitX(size, -initialRunDirection);
    runSegments.push(
      createSootSpriteRunSegment({
        startX: switchX,
        endX: switchedExitX,
        startDistance: runSegments[0].endDistance,
        groundY,
      })
    );
  }

  const exitX = runSegments[runSegments.length - 1].endX;
  const runLength = runSegments.reduce((total, segment) => total + segment.length, 0);
  const totalPathLength = Math.max(1, fallLength + runLength);
  const timedRunSegments = applySootSpriteRunSegmentTiming({
    fallLength,
    pathSpeed,
    runSegments,
    switchSpeedMultiplier: directionSwitchSpeedMultiplier,
  });
  const fallDuration = fallLength / pathSpeed;
  const totalPathDuration =
    timedRunSegments[timedRunSegments.length - 1]?.endTime || fallDuration;
  const measuredTrajectory = {
    ...trajectory,
    directionSwitchDelay,
    directionSwitchRoll,
    directionSwitchSpeedMultiplier,
    didSwitchDirection: shouldSwitchDirection,
    duration: totalPathDuration,
    exitX,
    fallDuration,
    fallLength,
    fallSamples,
    landingProgress: fallDuration / totalPathDuration,
    pathSpeed,
    runSegments: timedRunSegments,
    runLength,
    totalPathDuration,
    totalPathLength,
  };
  const fallQuarter = getSootSpriteFallPointAtDistance(
    measuredTrajectory,
    fallLength * 0.25
  );
  const fallMidpoint = getSootSpriteFallPointAtDistance(
    measuredTrajectory,
    fallLength * 0.5
  );
  const fallThreeQuarter = getSootSpriteFallPointAtDistance(
    measuredTrajectory,
    fallLength * 0.75
  );

  return {
    ...measuredTrajectory,
    fallQuarterX: fallQuarter.x,
    fallQuarterY: fallQuarter.y,
    fallMidpointX: fallMidpoint.x,
    fallMidpointY: fallMidpoint.y,
    fallThreeQuarterX: fallThreeQuarter.x,
    fallThreeQuarterY: fallThreeQuarter.y,
  };
};

const getSootSpriteTrajectoryPoint = (trajectory, progress) => {
  const clampedProgress = Math.min(1, Math.max(0, progress));
  const elapsedTime = clampedProgress * trajectory.duration;
  if (elapsedTime <= trajectory.fallDuration) {
    return getSootSpriteFallPointAtDistance(
      trajectory,
      elapsedTime * trajectory.pathSpeed
    );
  }

  const segment =
    trajectory.runSegments.find((candidate) => elapsedTime <= candidate.endTime) ||
    trajectory.runSegments[trajectory.runSegments.length - 1];
  const segmentProgress =
    (elapsedTime - segment.startTime) / Math.max(1, segment.duration);
  return {
    x: segment.startX + (segment.endX - segment.startX) * segmentProgress,
    y: segment.y,
  };
};

const getSootSpriteAirTrailProgress = (trajectory) => {
  const start = 0.08;
  const end = Math.max(start, Math.min(0.92, trajectory.landingProgress - 0.04));
  return randomSootSpriteValue(start, end);
};

const getSootSpriteGroundRunProgress = (trajectory) => {
  const start = Math.min(0.96, Math.max(0.08, trajectory.landingProgress + 0.04));
  return randomSootSpriteValue(start, 0.96);
};

const createSootSpriteElement = (index, trajectory, { paused = false } = {}) => {
  const sprite = document.createElement("span");
  sprite.className = "soot-sprite";
  sprite.setAttribute("aria-hidden", "true");

  setSootSpritePx(sprite, "--soot-x0", trajectory.startX);
  setSootSpritePx(sprite, "--soot-y0", trajectory.startY);
  setSootSpritePx(sprite, "--soot-x-fall-25", trajectory.fallQuarterX);
  setSootSpritePx(sprite, "--soot-y-fall-25", trajectory.fallQuarterY);
  setSootSpritePx(sprite, "--soot-x-fall-50", trajectory.fallMidpointX);
  setSootSpritePx(sprite, "--soot-y-fall-50", trajectory.fallMidpointY);
  setSootSpritePx(sprite, "--soot-x-fall-75", trajectory.fallThreeQuarterX);
  setSootSpritePx(sprite, "--soot-y-fall-75", trajectory.fallThreeQuarterY);
  setSootSpritePx(sprite, "--soot-x-land", trajectory.landingX);
  setSootSpritePx(sprite, "--soot-y-land", trajectory.groundY);
  setSootSpritePx(sprite, "--soot-x3", trajectory.exitX);
  setSootSpritePx(sprite, "--soot-y3", trajectory.exitY);
  setSootSpritePx(sprite, "--soot-size", trajectory.size);
  sprite.style.setProperty("--soot-delay", `${trajectory.delay}ms`);
  sprite.style.setProperty("--soot-duration", `${trajectory.duration}ms`);
  sprite.style.setProperty("--soot-run-scale", String(trajectory.runScale));
  sprite.style.setProperty(
    "--soot-body-radius",
    `${Math.round(randomSootSpriteValue(42, 58))}% ${Math.round(
      randomSootSpriteValue(42, 58)
    )}% ${Math.round(randomSootSpriteValue(42, 58))}% ${Math.round(
      randomSootSpriteValue(42, 58)
    )}% / ${Math.round(randomSootSpriteValue(42, 58))}% ${Math.round(
      randomSootSpriteValue(42, 58)
    )}% ${Math.round(randomSootSpriteValue(42, 58))}% ${Math.round(
      randomSootSpriteValue(42, 58)
    )}%`
  );
  sprite.style.setProperty("--soot-wobble-delay", `${index * -83}ms`);
  sprite.style.setProperty("--soot-left-eye-width", `${randomSootSpriteValue(7, 10).toFixed(1)}px`);
  sprite.style.setProperty("--soot-left-eye-height", `${randomSootSpriteValue(8, 12).toFixed(1)}px`);
  sprite.style.setProperty("--soot-right-eye-width", `${randomSootSpriteValue(7, 10).toFixed(1)}px`);
  sprite.style.setProperty("--soot-right-eye-height", `${randomSootSpriteValue(8, 12).toFixed(1)}px`);
  sprite.style.setProperty("--soot-left-eye-rotate", `${randomSootSpriteValue(-10, 9).toFixed(1)}deg`);
  sprite.style.setProperty("--soot-right-eye-rotate", `${randomSootSpriteValue(-9, 10).toFixed(1)}deg`);

  const body = document.createElement("span");
  body.className = "soot-sprite-body";
  const leftEye = document.createElement("span");
  leftEye.className = "soot-sprite-eye soot-sprite-eye--left";
  const rightEye = document.createElement("span");
  rightEye.className = "soot-sprite-eye soot-sprite-eye--right";
  body.append(leftEye, rightEye);
  sprite.append(body);
  const motion = animateSootSpriteElement(sprite, trajectory);
  if (paused && motion) {
    motion.pause();
    sootSpriteMotionAnimations.set(sprite, motion);
  }
  return sprite;
};

const createSootCandyElement = (launchRect) => {
  const candy = document.createElement("span");
  candy.className = "soot-star-candy";
  candy.setAttribute("aria-hidden", "true");
  const size = Math.round(randomSootSpriteValue(8, 14));
  const x0 = launchRect.left + randomSootSpriteValue(8, Math.max(10, launchRect.width - 16));
  const y0 = launchRect.top + randomSootSpriteValue(8, Math.max(10, launchRect.height - 12));
  const trajectory = createSootCandyTrajectory({
    startX: x0,
    startY: y0,
    size,
    minHorizontalTravel: 44,
    maxHorizontalTravel: 250,
  });
  const spin = randomSootSpriteValue(-820, 820);
  setSootCandyTrajectoryProperties(candy, trajectory);
  setSootSpritePx(candy, "--candy-size", size);
  candy.style.setProperty("--candy-color", randomSootCandyColor());
  setSootCandyTimingProperties(candy, {
    delay: randomSootSpriteValue(140, 520),
    fallDuration: randomSootSpriteValue(3600, 4800),
  });
  setSootCandySpinProperties(candy, spin);
  return candy;
};

const createSootTrailCandyElement = (trajectory, progress) => {
  const candy = document.createElement("span");
  candy.className = "soot-star-candy soot-star-candy--trail";
  candy.setAttribute("aria-hidden", "true");
  const size = Math.round(randomSootSpriteValue(6, 11));
  const origin = getSootSpriteTrajectoryPoint(trajectory, progress);
  const x0 = origin.x + randomSootSpriteValue(-12, 12);
  const y0 = origin.y + randomSootSpriteValue(-10, 14);
  const candyTrajectory = createSootCandyTrajectory({
    startX: x0,
    startY: y0,
    size,
    minHorizontalTravel: 36,
    maxHorizontalTravel: 176,
  });
  const spin = randomSootSpriteValue(-620, 620);
  setSootCandyTrajectoryProperties(candy, candyTrajectory);
  setSootSpritePx(candy, "--candy-size", size);
  candy.style.setProperty("--candy-color", randomSootCandyColor());
  setSootCandyTimingProperties(candy, {
    delay:
      trajectory.delay +
      trajectory.duration * progress +
      randomSootSpriteValue(-90, 140),
    fallDuration: randomSootSpriteValue(3200, 4300),
  });
  setSootCandySpinProperties(candy, spin);
  return candy;
};

const createSootPuffElement = (launchRect, large = false) => {
  const puff = document.createElement("span");
  puff.className = large ? "soot-puff soot-puff--large" : "soot-puff";
  puff.setAttribute("aria-hidden", "true");
  const size = randomSootSpriteValue(large ? 192 : 84, large ? 380 : 208);
  const x0 = launchRect.left + randomSootSpriteValue(-20, launchRect.width + 20);
  const y0 = launchRect.top + randomSootSpriteValue(-14, launchRect.height + 20);
  setSootSpritePx(puff, "--puff-x0", x0);
  setSootSpritePx(puff, "--puff-y0", y0);
  setSootSpritePx(puff, "--puff-x1", x0 + randomSootSpriteValue(-320, 320));
  setSootSpritePx(puff, "--puff-y1", y0 + randomSootSpriteValue(large ? -140 : -210, large ? 230 : 150));
  setSootSpritePx(puff, "--puff-size", size);
  puff.style.setProperty(
    "--puff-delay",
    `${randomSootSpriteValue(40, 360)}ms`
  );
  puff.style.setProperty("--puff-duration", `${randomSootSpriteValue(5400, 7600)}ms`);
  return puff;
};

const createSootTrailPuffElement = (trajectory, index, progress) => {
  const puff = document.createElement("span");
  puff.className = index % 5 === 0 ? "soot-puff soot-puff--trail soot-puff--large" : "soot-puff soot-puff--trail";
  puff.setAttribute("aria-hidden", "true");
  const direction = trajectory.exitX < trajectory.landingX ? -1 : 1;
  const size = randomSootSpriteValue(76, 196);
  const origin = getSootSpriteTrajectoryPoint(trajectory, progress);
  const x0 = origin.x + direction * randomSootSpriteValue(4, 28);
  const y0 = origin.y + randomSootSpriteValue(-10, 18);
  setSootSpritePx(puff, "--puff-x0", x0);
  setSootSpritePx(puff, "--puff-y0", y0);
  setSootSpritePx(puff, "--puff-x1", x0 + direction * randomSootSpriteValue(70, 240));
  setSootSpritePx(puff, "--puff-y1", y0 + randomSootSpriteValue(-46, 54));
  setSootSpritePx(puff, "--puff-size", size);
  puff.style.setProperty(
    "--puff-delay",
    `${trajectory.delay + trajectory.duration * progress + randomSootSpriteValue(-120, 180)}ms`
  );
  puff.style.setProperty("--puff-duration", `${randomSootSpriteValue(5300, 7300)}ms`);
  return puff;
};

const showSootSpritesSwarm = (launchRect = getSootSpritesLaunchRect()) => {
  cleanupSootSpritesOverlay();
  const overlay = document.createElement("div");
  overlay.className = "soot-sprites-swarm is-staged";
  overlay.style.zIndex = String(getSootSpritesStagedZIndex());
  overlay.setAttribute("aria-hidden", "true");

  const spriteCount =
    window.innerWidth < 560 ? SOOT_SPRITES_MOBILE_COUNT : SOOT_SPRITES_DESKTOP_COUNT;
  const spawnGrid = createSootSpriteSpawnGrid(launchRect, spriteCount);
  const trajectories = spawnGrid.map((startPoint) =>
    createSootSpriteTrajectory(launchRect, { startPoint })
  );
  trajectories.forEach((trajectory, index) => {
    overlay.append(createSootSpriteElement(index, trajectory, { paused: true }));
  });

  const airTrailCandyCount = Math.round(
    spriteCount * SOOT_SPRITES_AIR_TRAIL_CANDIES_PER_SPRITE
  );
  for (let index = 0; index < airTrailCandyCount; index += 1) {
    const trajectory = trajectories[index % trajectories.length];
    overlay.append(
      createSootTrailCandyElement(trajectory, getSootSpriteAirTrailProgress(trajectory))
    );
  }

  // Ground-run candy is intentionally twice as dense as the airborne trail.
  const groundRunCandyCount = Math.round(
    spriteCount *
      SOOT_SPRITES_AIR_TRAIL_CANDIES_PER_SPRITE *
      SOOT_SPRITES_GROUND_RUN_CANDY_MULTIPLIER
  );
  for (let index = 0; index < groundRunCandyCount; index += 1) {
    const trajectory = trajectories[index % trajectories.length];
    overlay.append(
      createSootTrailCandyElement(trajectory, getSootSpriteGroundRunProgress(trajectory))
    );
  }

  const trailPuffCount = Math.round(spriteCount * 1.4);
  for (let index = 0; index < trailPuffCount; index += 1) {
    const progress = 0.04 + ((index * 0.13) % 0.92);
    overlay.append(
      createSootTrailPuffElement(trajectories[index % trajectories.length], index, progress)
    );
  }

  const candyCount = Math.round(spriteCount * 1.28);
  for (let index = 0; index < candyCount; index += 1) {
    overlay.append(createSootCandyElement(launchRect));
  }

  const puffCount = Math.round(spriteCount * 0.48);
  for (let index = 0; index < puffCount; index += 1) {
    overlay.append(createSootPuffElement(launchRect, index % 5 === 0));
  }

  document.body.append(overlay);
  document.body.classList.add("is-soot-sprites-active");
  sootSpritesOverlay = overlay;
  sootSpritesCleanupTimer = window.setTimeout(cleanupSootSpritesOverlay, SOOT_SPRITES_CLEANUP_MS);
  return overlay;
};

const releaseSootSpritesSwarm = () => {
  const overlay = sootSpritesOverlay;
  if (!overlay?.classList.contains("is-staged")) return;
  overlay.classList.remove("is-staged");
  overlay.style.removeProperty("z-index");
  overlay.querySelectorAll(".soot-sprite").forEach((sprite) => {
    sootSpriteMotionAnimations.get(sprite)?.play();
  });
};

const showSootSpritesWindow = () => {
  const didOpen = showManagedRandomEventWindow(sootSpritesWindow, {
    clampAfterMediaLoad: true,
  });
  if (didOpen) reserveSootSpritesSpawnLane();
};

const closeSootSpritesWindow = () => {
  clearSootSpritesLifecycleTimers();
  setSootSpritesWindowLoading(false);
  closeManagedRandomEventWindow(sootSpritesWindow);
};

const inspectSootSpritesGpu = () => {
  if (!sootSpritesWindow || sootSpritesWindow.classList.contains("is-hidden")) return;
  const launchRect = getSootSpritesLaunchRect();
  clearSootSpritesLifecycleTimers();
  setSootSpritesWindowLoading(true);
  sootSpritesRevealTimer = window.setTimeout(() => {
    sootSpritesRevealTimer = null;
    const overlay = showSootSpritesSwarm(launchRect);
    // The procedural sprites are ready after their nodes have been committed to a frame.
    window.requestAnimationFrame(() => {
      if (overlay !== sootSpritesOverlay) return;
      sootSpritesWindowHoldTimer = window.setTimeout(() => {
        sootSpritesWindowHoldTimer = null;
        setSootSpritesWindowLoading(false);
        closeManagedRandomEventWindow(sootSpritesWindow);
      }, SOOT_SPRITES_WINDOW_HOLD_AFTER_LOAD_MS);
    });
  }, SOOT_SPRITES_REVEAL_DELAY_MS);
};

const isNatarajaVisible = () => isManagedRandomEventWindowVisible(natarajaWindow);

const playNatarajaVideo = () => {
  if (!natarajaVideo) return;
  natarajaVideo.play().catch(() => undefined);
};

const resetNatarajaVideo = () => {
  if (!natarajaVideo) return;
  natarajaVideo.pause();
  try {
    natarajaVideo.currentTime = 0;
  } catch (error) {
    // Some browsers reject seeking before video metadata is ready.
  }
};

const showNatarajaWindow = () => {
  const didOpen = showManagedRandomEventWindow(natarajaWindow, {
    clampAfterMediaLoad: true,
  });
  if (didOpen) requestAnimationFrame(playNatarajaVideo);
};

const closeNatarajaWindow = () => {
  resetNatarajaVideo();
  closeManagedRandomEventWindow(natarajaWindow);
};

const isNobleSteedVisible = () =>
  Boolean(
    nobleSteedResultTimer ||
      isManagedRandomEventWindowVisible(nobleSteedWindow) ||
      isManagedRandomEventWindowVisible(nobleSteedResultWindow)
  );

const clearNobleSteedResultTimer = () => {
  if (!nobleSteedResultTimer) return;
  window.clearTimeout(nobleSteedResultTimer);
  nobleSteedResultTimer = null;
};

const getRandomEventWindowPosition = (win) => {
  if (!win) return null;
  const rect = win.getBoundingClientRect();
  const styleLeft = Number.parseFloat(win.style.left);
  const styleTop = Number.parseFloat(win.style.top);
  return {
    left: Number.isFinite(styleLeft) ? styleLeft : rect.left,
    top: Number.isFinite(styleTop) ? styleTop : rect.top,
  };
};

const showNobleSteedWindow = () => {
  clearNobleSteedResultTimer();
  nobleSteedResultPosition = null;
  closeManagedRandomEventWindow(nobleSteedResultWindow);
  showManagedRandomEventWindow(nobleSteedWindow, { clampAfterMediaLoad: true });
};

const closeNobleSteedWindow = () => {
  clearNobleSteedResultTimer();
  nobleSteedResultPosition = null;
  closeManagedRandomEventWindow(nobleSteedWindow);
};

const showNobleSteedResultWindow = () => {
  nobleSteedResultTimer = null;
  const didOpen = showManagedRandomEventWindow(nobleSteedResultWindow, {
    clampAfterMediaLoad: true,
  });
  if (didOpen && nobleSteedResultPosition) {
    setRandomEventWindowPosition(
      nobleSteedResultWindow,
      nobleSteedResultPosition.left,
      nobleSteedResultPosition.top
    );
  }
};

const acceptNobleSteedOffer = () => {
  if (!nobleSteedWindow || nobleSteedWindow.classList.contains("is-hidden")) return;
  clearNobleSteedResultTimer();
  nobleSteedResultPosition = getRandomEventWindowPosition(nobleSteedWindow);
  closeManagedRandomEventWindow(nobleSteedWindow);
  nobleSteedResultTimer = window.setTimeout(showNobleSteedResultWindow, 2000);
};

const closeNobleSteedResultWindow = () => {
  clearNobleSteedResultTimer();
  nobleSteedResultPosition = null;
  closeManagedRandomEventWindow(nobleSteedResultWindow);
};

const TOXIC_JUNGLE_ASSETS = Object.freeze({
  background: "assets/random%20events/toxic-jungle.webp",
  nausicaa: "assets/random%20events/nausicaa.jpg",
});
const TOXIC_JUNGLE_STAGE_PROMPT = "prompt";
const TOXIC_JUNGLE_STAGE_ACTIVE = "active";
const TOXIC_JUNGLE_STAGE_COMPLETE = "complete";
const TOXIC_JUNGLE_SPORE_TARGET = 10;
const TOXIC_JUNGLE_ACTIVE_SPORES_PER_TYPE = 3;
const TOXIC_JUNGLE_PROMPT =
  "Hey! Can you help me collect some spores?";
const TOXIC_JUNGLE_COMPLETE_MESSAGE =
  "Thanks for the help! Watch your back out there.";
const TOXIC_JUNGLE_SPORE_TYPES = Object.freeze([
  { id: "blue", label: "Blue", color: "#a9cbd4" },
  { id: "red", label: "Red", color: "#d6a2a0" },
  { id: "white", label: "White", color: "#d7d4c6" },
]);

let toxicJungleStage = TOXIC_JUNGLE_STAGE_PROMPT;
let toxicJungleCounts = {};
let toxicJungleSporeSequence = 0;

const createToxicJungleCounts = () =>
  Object.fromEntries(TOXIC_JUNGLE_SPORE_TYPES.map((type) => [type.id, 0]));

const isToxicJungleVisible = () =>
  isManagedRandomEventWindowVisible(toxicJungleWindow);

const setToxicJungleElementHidden = (element, hidden) => {
  if (!element) return;
  element.classList.toggle("is-hidden", hidden);
  element.setAttribute("aria-hidden", String(hidden));
};

const clearToxicJungleTyping = () => {
  clearPokemonStyleDialogueTyping(toxicJungleDialogText);
};

const setToxicJungleDialog = (message, { instant = false } = {}) => {
  if (instant) {
    setPokemonStyleDialogueText(toxicJungleDialogText, message, {
      instant: true,
      arrow: true,
    });
    return;
  }
  setPokemonStyleSegmentedDialogue(
    toxicJungleDialogText,
    [{ text: message }],
    { arrow: true }
  );
};

const renderToxicJungleCounters = () => {
  if (!toxicJungleCounters) return;
  const rows = TOXIC_JUNGLE_SPORE_TYPES.map((type) => {
    const row = document.createElement("span");
    row.className = "toxic-jungle-counter-row";

    const symbol = document.createElement("span");
    symbol.className = `toxic-jungle-counter-symbol toxic-jungle-counter-symbol--${type.id}`;
    symbol.style.setProperty("--spore-color", type.color);
    symbol.setAttribute("aria-hidden", "true");

    const count = document.createElement("span");
    count.textContent = `${type.label}: ${toxicJungleCounts[type.id] || 0}/${TOXIC_JUNGLE_SPORE_TARGET}`;

    row.append(symbol, count);
    return row;
  });
  toxicJungleCounters.replaceChildren(...rows);
};

const getToxicJungleSporeTravel = () => {
  const width = toxicJungleScene?.clientWidth || 760;
  return `${Math.max(width + 72, 420)}px`;
};

const spawnToxicJungleSpore = (type) => {
  if (
    !toxicJungleSpores ||
    toxicJungleStage !== TOXIC_JUNGLE_STAGE_ACTIVE ||
    (toxicJungleCounts[type.id] || 0) >= TOXIC_JUNGLE_SPORE_TARGET
  ) {
    return;
  }

  toxicJungleSporeSequence += 1;
  const button = document.createElement("button");
  button.type = "button";
  button.className = `toxic-jungle-spore toxic-jungle-spore--${type.id}`;
  button.dataset.toxicJungleSpore = type.id;
  button.style.setProperty("--spore-color", type.color);
  button.style.setProperty("--spore-y", `${18 + Math.random() * 58}%`);
  button.style.setProperty("--spore-scale", `${0.72 + Math.random() * 0.42}`);
  button.style.setProperty("--spore-duration", `${9 + Math.random() * 5}s`);
  button.style.setProperty("--spore-delay", "0s");
  button.style.setProperty("--spore-travel", getToxicJungleSporeTravel());
  button.style.setProperty("--spore-bob-delay", `${toxicJungleSporeSequence * -0.17}s`);
  button.setAttribute("aria-label", `Collect ${type.label.toLowerCase()} spore`);
  const sporeCore = document.createElement("span");
  sporeCore.className = "toxic-jungle-spore-core";
  sporeCore.setAttribute("aria-hidden", "true");
  button.append(sporeCore);
  toxicJungleSpores.append(button);
};

const clearToxicJungleSpores = () => {
  toxicJungleSpores?.replaceChildren();
};

const populateToxicJungleSpores = () => {
  clearToxicJungleSpores();
  TOXIC_JUNGLE_SPORE_TYPES.forEach((type) => {
    for (let count = 0; count < TOXIC_JUNGLE_ACTIVE_SPORES_PER_TYPE; count += 1) {
      spawnToxicJungleSpore(type);
    }
  });
};

const isToxicJungleComplete = () =>
  TOXIC_JUNGLE_SPORE_TYPES.every(
    (type) => (toxicJungleCounts[type.id] || 0) >= TOXIC_JUNGLE_SPORE_TARGET
  );

const completeToxicJungle = () => {
  toxicJungleStage = TOXIC_JUNGLE_STAGE_COMPLETE;
  clearToxicJungleSpores();
  toxicJungleWindow?.classList.add("is-complete");
  setToxicJungleElementHidden(toxicJungleDialog, false);
  setToxicJungleElementHidden(toxicJungleStart, true);
  setToxicJungleElementHidden(toxicJungleDecline, true);
  toxicJungleDialogActions?.classList.add("is-hidden");
  toxicJungleDialogActions?.setAttribute("aria-hidden", "true");
  setToxicJungleDialog(TOXIC_JUNGLE_COMPLETE_MESSAGE);
};

const collectToxicJungleSpore = (button) => {
  if (!button || toxicJungleStage !== TOXIC_JUNGLE_STAGE_ACTIVE) return;
  const type = TOXIC_JUNGLE_SPORE_TYPES.find(
    (candidate) => candidate.id === button.dataset.toxicJungleSpore
  );
  if (!type) return;

  toxicJungleCounts[type.id] = Math.min(
    TOXIC_JUNGLE_SPORE_TARGET,
    (toxicJungleCounts[type.id] || 0) + 1
  );
  button.remove();
  renderToxicJungleCounters();

  if (isToxicJungleComplete()) {
    completeToxicJungle();
    return;
  }

  spawnToxicJungleSpore(type);
};

const resetToxicJungleEvent = ({ typewrite = false } = {}) => {
  toxicJungleStage = TOXIC_JUNGLE_STAGE_PROMPT;
  toxicJungleCounts = createToxicJungleCounts();
  toxicJungleSporeSequence = 0;
  clearToxicJungleSpores();
  clearToxicJungleTyping();
  toxicJungleWindow?.classList.remove("is-complete");
  setToxicJungleElementHidden(toxicJungleDialog, false);
  setToxicJungleElementHidden(toxicJungleCounters, true);
  setToxicJungleElementHidden(toxicJungleStart, false);
  setToxicJungleElementHidden(toxicJungleDecline, false);
  toxicJungleDialogActions?.classList.remove("is-hidden");
  toxicJungleDialogActions?.setAttribute("aria-hidden", "false");
  setToxicJungleDialog(TOXIC_JUNGLE_PROMPT, { instant: !typewrite });
  renderToxicJungleCounters();
};

const showToxicJungleWindow = () => {
  const didOpen = showManagedRandomEventWindow(toxicJungleWindow, {
    beforeShow: () => resetToxicJungleEvent({ typewrite: true }),
    clampAfterMediaLoad: true,
  });
  if (!didOpen && isToxicJungleVisible()) {
    toxicJungleWindow.style.zIndex = String(topZ++);
  }
};

const closeToxicJungleWindow = () => {
  clearToxicJungleTyping();
  closeManagedRandomEventWindow(toxicJungleWindow);
};

const startToxicJungleCollection = () => {
  if (!isToxicJungleVisible()) return;
  clearToxicJungleTyping();
  toxicJungleStage = TOXIC_JUNGLE_STAGE_ACTIVE;
  setToxicJungleElementHidden(toxicJungleDialog, true);
  setToxicJungleElementHidden(toxicJungleCounters, false);
  renderToxicJungleCounters();
  populateToxicJungleSpores();
};

const LANCER_BATTLE_CLASH_VIDEO =
  "https://imgix.bustle.com/inverse/8d/d9/86/e4/92b5/4dec/b80e/3402288d9a18/giphy-9gif.gif?w=825&h=464&fit=max&fm=mp4";
const LANCER_BATTLE_WIN_VIDEO_START_SECONDS = 29.5;
const LANCER_BATTLE_WIN_VIDEO_END_SECONDS = 36.5;
const LANCER_BATTLE_WIN_VIDEO_SRC =
  "assets/random%20events/lancer-battle/lancer-battle-win.mp4";
const LANCER_BATTLE_LOSS_VIDEO_START_SECONDS = 21.5;
const LANCER_BATTLE_LOSS_VIDEO_END_SECONDS = 25;
const LANCER_BATTLE_LOSS_VIDEO_SRC =
  "assets/random%20events/lancer-battle/lancer-battle-loss.mp4";
const LANCER_BATTLE_START_PROGRESS = FATE_START_PROGRESS;
const LANCER_BATTLE_PUSH_GAIN = FATE_PRESS_GAIN;
const LANCER_BATTLE_DRAIN_INTERVAL_MS = FATE_DRAIN_INTERVAL_MS;
const LANCER_BATTLE_DRAIN_AMOUNT = FATE_DRAIN_AMOUNT;
const LANCER_BATTLE_FALLBACK_CLASH_MS = 3600;
const LANCER_BATTLE_BOOMERANG_SECONDS = 0.5;
const LANCER_BATTLE_BOOMERANG_START_BUFFER_SECONDS = 0.05;
const LANCER_BATTLE_BOOMERANG_STEP = 0.033;
const LANCER_BATTLE_CLICK_COUNTER_PROBABILITY = 0.4;
const LANCER_BATTLE_WIN_CLIP_MS =
  (LANCER_BATTLE_WIN_VIDEO_END_SECONDS - LANCER_BATTLE_WIN_VIDEO_START_SECONDS) * 1000;
const LANCER_BATTLE_LOSS_CLIP_MS =
  (LANCER_BATTLE_LOSS_VIDEO_END_SECONDS - LANCER_BATTLE_LOSS_VIDEO_START_SECONDS) * 1000;

const LANCER_BATTLE_STAGES = Object.freeze({
  ready: "ready",
  intro: "intro",
  active: "active",
  resolving: "resolving",
  win: "win",
  loss: "loss",
  final: "final",
  idle: "idle",
});

const isLancerBattleVisible = () =>
  isManagedRandomEventWindowVisible(lancerBattleWindow);

const shouldKeepLancerBattleResultMediaPlaying = (win) =>
  win === lancerBattleWindow &&
  (lancerBattleState === LANCER_BATTLE_STAGES.win ||
    lancerBattleState === LANCER_BATTLE_STAGES.loss);

const setLancerBattleStatus = (message) => {
  if (lancerBattleStatus) lancerBattleStatus.textContent = message;
};

const showLancerBattleStage = (stage) => {
  lancerBattleReadyStage?.classList.toggle("is-hidden", stage !== "ready");
  lancerBattleClashStage?.classList.toggle("is-hidden", stage !== "clash");
  lancerBattleResultStage?.classList.toggle("is-hidden", stage !== "result");
  lancerBattleFinalStage?.classList.toggle("is-hidden", stage !== "final");
  lancerBattleWindow?.classList.toggle("is-ready", stage === "ready");
};

const updateLancerBattleProgress = () => {
  const progress = Math.min(100, Math.max(0, lancerBattleProgressValue));
  if (lancerBattleProgressBar) {
    lancerBattleProgressBar.style.width = `${progress}%`;
  }
  if (lancerBattleProgress) {
    lancerBattleProgress.setAttribute("aria-valuenow", Math.round(progress));
  }
};

const clearLancerBattleVideo = () => {
  if (!lancerBattleClashVideo) return;
  lancerBattleClashVideo.pause();
  lancerBattleClashVideo.currentTime = 0;
};

const clearLancerBattleLightning = () => {
  if (lancerBattleLightningFrame) {
    cancelAnimationFrame(lancerBattleLightningFrame);
    lancerBattleLightningFrame = null;
  }
  clearLightningCanvas(lancerBattleLightningCanvas);
};

const clearLancerBattleTimers = () => {
  if (lancerBattleDrainTimer) {
    clearInterval(lancerBattleDrainTimer);
    lancerBattleDrainTimer = null;
  }
  if (lancerBattleClashTimer) {
    clearTimeout(lancerBattleClashTimer);
    lancerBattleClashTimer = null;
  }
  if (lancerBattleLightningTimer) {
    clearTimeout(lancerBattleLightningTimer);
    lancerBattleLightningTimer = null;
  }
  if (lancerBattleBoomerangFrame) {
    cancelAnimationFrame(lancerBattleBoomerangFrame);
    lancerBattleBoomerangFrame = null;
  }
  if (lancerBattleResolveTimer) {
    clearTimeout(lancerBattleResolveTimer);
    lancerBattleResolveTimer = null;
  }
  if (lancerBattleResultTimer) {
    clearTimeout(lancerBattleResultTimer);
    lancerBattleResultTimer = null;
  }
  lancerBattleWindow?.classList.remove("is-striking");
  clearLancerBattleLightning();
};

const clearLancerBattleResultMedia = () => {
  lancerBattleResultVideoToken += 1;
  if (lancerBattleResultImage) {
    lancerBattleResultImage.removeAttribute("src");
    lancerBattleResultImage.classList.remove("is-hidden");
  }
  if (lancerBattleResultVideo) {
    lancerBattleResultVideo.pause();
    lancerBattleResultVideo.removeAttribute("src");
    lancerBattleResultVideo.load();
    lancerBattleResultVideo.classList.add("is-hidden");
  }
};

const setLancerBattleResultImage = (src) => {
  if (!lancerBattleResultImage) return;
  if (lancerBattleResultVideo) {
    lancerBattleResultVideo.pause();
    lancerBattleResultVideo.removeAttribute("src");
    lancerBattleResultVideo.load();
    lancerBattleResultVideo.classList.add("is-hidden");
  }
  lancerBattleResultImage.classList.remove("is-hidden");
  lancerBattleResultImage.src = `${src}${src.includes("?") ? "&" : "?"}replay=${Date.now()}`;
  lancerBattleResultImage.alt = "";
};

const playLancerBattleResultVideo = (src, token, onPlaybackStarted = () => {}) => {
  let hasStartedPlayback = false;
  const markStarted = () => {
    if (token !== lancerBattleResultVideoToken) return;
    if (hasStartedPlayback) return;
    hasStartedPlayback = true;
    onPlaybackStarted();
  };
  if (lancerBattleResultImage) {
    lancerBattleResultImage.removeAttribute("src");
    lancerBattleResultImage.classList.add("is-hidden");
  }
  lancerBattleResultVideo.pause();
  lancerBattleResultVideo.currentTime = 0;
  lancerBattleResultVideo.src = `${src}${src.includes("?") ? "&" : "?"}replay=${Date.now()}`;
  lancerBattleResultVideo.classList.remove("is-hidden");
  lancerBattleResultVideo.addEventListener("playing", markStarted, { once: true });
  const playRequest = lancerBattleResultVideo.play();
  if (playRequest && typeof playRequest.then === "function") {
    playRequest.then(markStarted).catch(markStarted);
  } else {
    markStarted();
  }
};

const setLancerBattleResultVideo = (src, options = {}) => {
  if (!lancerBattleResultVideo) return;
  lancerBattleResultVideoToken += 1;
  playLancerBattleResultVideo(src, lancerBattleResultVideoToken, options.onPlaybackStarted);
};

const resetLancerBattleWindow = () => {
  clearLancerBattleTimers();
  clearLancerBattleVideo();
  lancerBattleOpenFinalAfterClose = false;
  lancerBattleState = LANCER_BATTLE_STAGES.ready;
  lancerBattleProgressValue = LANCER_BATTLE_START_PROGRESS;
  lancerBattleBoomerangDirection = 1;
  lancerBattleBoomerangStart = 0;
  lancerBattleBoomerangEnd = 0;
  updateLancerBattleProgress();
  lancerBattleWindow?.classList.remove(
    "is-clashing",
    "is-win",
    "is-loss",
    "is-final-alert"
  );
  if (lancerBattleTitle) lancerBattleTitle.textContent = "Lancer Duel";
  if (lancerBattlePush) {
    lancerBattlePush.disabled = true;
    lancerBattlePush.textContent = "Fight Back";
  }
  if (lancerBattleClose) lancerBattleClose.textContent = "Close";
  setLancerBattleStatus("Wait for the clash.");
  clearLancerBattleResultMedia();
  if (lancerBattleResultText) lancerBattleResultText.textContent = "";
  if (lancerBattleFinalText) lancerBattleFinalText.textContent = "";
  showLancerBattleStage("ready");
};

const startLancerBattleLightningStrike = () => {
  if (!lancerBattleLightningCanvas || !isLancerBattleVisible()) return;
  if (lancerBattleLightningFrame) cancelAnimationFrame(lancerBattleLightningFrame);
  const startedAt = performance.now();

  const render = (now) => {
    if (!isLancerBattleVisible()) {
      clearLancerBattleLightning();
      return;
    }
    const progress = Math.min(1, (now - startedAt) / FATE_LIGHTNING_DURATION_MS);
    const flicker = progress < 0.16 ? 1 : Math.random() > 0.32 ? 1 - progress * 0.42 : 0.18;
    const alpha = Math.max(0, flicker * (1 - progress * 0.36));
    drawLightningBorderFrame(
      lancerBattleLightningCanvas,
      alpha,
      YELLOW_LIGHTNING_PALETTE
    );

    if (progress < 1) {
      lancerBattleLightningFrame = requestAnimationFrame(render);
      return;
    }

    lancerBattleLightningFrame = null;
    clearLightningCanvas(lancerBattleLightningCanvas);
  };

  lancerBattleLightningFrame = requestAnimationFrame(render);
};

const pulseLancerBattleWindow = () => {
  if (!lancerBattleWindow) return;
  lancerBattleWindow.classList.remove("is-striking");
  void lancerBattleWindow.offsetWidth;
  lancerBattleWindow.classList.add("is-striking");
  startLancerBattleLightningStrike();
  if (lancerBattleLightningTimer) clearTimeout(lancerBattleLightningTimer);
  lancerBattleLightningTimer = setTimeout(() => {
    lancerBattleWindow.classList.remove("is-striking");
    lancerBattleLightningTimer = null;
  }, 240);
};

const updateLancerBattleBoomerangFrame = () => {
  if (
    !lancerBattleClashVideo ||
    lancerBattleState !== LANCER_BATTLE_STAGES.active
  ) {
    lancerBattleBoomerangFrame = null;
    return;
  }

  const current = lancerBattleClashVideo.currentTime;
  if (current >= lancerBattleBoomerangEnd) {
    lancerBattleBoomerangDirection = -1;
  } else if (current <= lancerBattleBoomerangStart) {
    lancerBattleBoomerangDirection = 1;
  }
  const nextTime =
    current + LANCER_BATTLE_BOOMERANG_STEP * lancerBattleBoomerangDirection;
  lancerBattleClashVideo.currentTime = Math.min(
    lancerBattleBoomerangEnd,
    Math.max(lancerBattleBoomerangStart, nextTime)
  );
  lancerBattleBoomerangFrame = requestAnimationFrame(
    updateLancerBattleBoomerangFrame
  );
};

const startLancerBattleBoomerang = () => {
  if (!lancerBattleClashVideo) return;
  const duration = Number.isFinite(lancerBattleClashVideo.duration)
    ? lancerBattleClashVideo.duration
    : 0;
  lancerBattleBoomerangEnd = Math.max(0.2, duration || lancerBattleClashVideo.currentTime);
  lancerBattleBoomerangStart = Math.max(
    0,
    lancerBattleBoomerangEnd - LANCER_BATTLE_BOOMERANG_SECONDS
  );
  lancerBattleBoomerangDirection = 1;
  lancerBattleClashVideo.pause();
  lancerBattleClashVideo.currentTime = lancerBattleBoomerangStart;
  if (lancerBattleBoomerangFrame) {
    cancelAnimationFrame(lancerBattleBoomerangFrame);
  }
  lancerBattleBoomerangFrame = requestAnimationFrame(
    updateLancerBattleBoomerangFrame
  );
};

const showLancerBattleFinalPrompt = (success) => {
  if (!success) {
    closeLancerBattleWindow();
    return;
  }
  lancerBattleState = LANCER_BATTLE_STAGES.final;
  lancerBattleWindow?.classList.add("is-final-alert");
  if (lancerBattleTitle) {
    lancerBattleTitle.textContent = "Duel Won";
  }
  clearLancerBattleResultMedia();
  if (lancerBattleFinalText) {
    lancerBattleFinalText.textContent = "Good job, Gear.";
  }
  if (lancerBattleClose) lancerBattleClose.textContent = "OK";
  showLancerBattleStage("final");
  requestAnimationFrame(() => {
    lancerBattleClose?.focus({ preventScroll: true });
  });
};

const reopenLancerBattleFinalPrompt = () => {
  if (!lancerBattleWindow) return;
  showLancerBattleFinalPrompt(true);
  lancerBattleWindow.classList.remove("is-hidden", "is-closing");
  lancerBattleWindow.setAttribute("aria-hidden", "false");
  positionRandomEventWindowInViewport(lancerBattleWindow);
  clampRandomEventWindowToViewport(lancerBattleWindow);
  lancerBattleWindow.style.zIndex = String(topZ++);
  restartWindowAnimation(lancerBattleWindow, "is-opening");
};

const transitionLancerBattleWinToFinalPrompt = () => {
  if (!lancerBattleWindow || lancerBattleWindow.classList.contains("is-hidden")) {
    showLancerBattleFinalPrompt(true);
    return;
  }
  lancerBattleOpenFinalAfterClose = true;
  lancerBattleWindow.setAttribute("aria-hidden", "true");
  restartWindowAnimation(lancerBattleWindow, "is-closing");
};

const queueLancerBattleResultCompletion = (success) => {
  if (lancerBattleResultTimer) {
    clearTimeout(lancerBattleResultTimer);
  }
  lancerBattleResultTimer = setTimeout(() => {
    lancerBattleResultTimer = null;
    if (success) {
      transitionLancerBattleWinToFinalPrompt();
    } else {
      closeLancerBattleWindow();
    }
  }, success ? LANCER_BATTLE_WIN_CLIP_MS : LANCER_BATTLE_LOSS_CLIP_MS);
};

const showLancerBattleResult = (success) => {
  lancerBattleState = success ? LANCER_BATTLE_STAGES.win : LANCER_BATTLE_STAGES.loss;
  lancerBattleWindow?.classList.toggle("is-win", success);
  lancerBattleWindow?.classList.toggle("is-loss", !success);
  if (lancerBattleTitle) {
    lancerBattleTitle.textContent = success ? "Enemy Executed" : "You get Overwhelmed";
  }
  if (success) {
    setLancerBattleResultVideo(LANCER_BATTLE_WIN_VIDEO_SRC, {
      onPlaybackStarted: () => queueLancerBattleResultCompletion(true),
    });
  } else {
    setLancerBattleResultVideo(LANCER_BATTLE_LOSS_VIDEO_SRC, {
      onPlaybackStarted: () => queueLancerBattleResultCompletion(false),
    });
  }
  if (lancerBattleResultText) {
    lancerBattleResultText.textContent = success ? "Marcus wins the blade lock." : "";
  }
  showLancerBattleStage("result");
};

const finishLancerBattle = (success) => {
  if (lancerBattleState !== LANCER_BATTLE_STAGES.active) return;
  lancerBattleState = LANCER_BATTLE_STAGES.resolving;
  clearLancerBattleTimers();
  clearLancerBattleVideo();
  lancerBattleWindow?.classList.remove("is-clashing");
  lancerBattleProgressValue = success ? 100 : 0;
  updateLancerBattleProgress();
  if (lancerBattlePush) lancerBattlePush.disabled = true;
  lancerBattleResolveTimer = setTimeout(() => {
    lancerBattleResolveTimer = null;
    showLancerBattleResult(success);
  }, 420);
};

const tickLancerBattleDrain = () => {
  if (lancerBattleState !== LANCER_BATTLE_STAGES.active) return;
  lancerBattleProgressValue = Math.max(
    0,
    lancerBattleProgressValue - LANCER_BATTLE_DRAIN_AMOUNT
  );
  updateLancerBattleProgress();
  if (lancerBattleProgressValue <= 0) finishLancerBattle(false);
};

const startLancerBattleDrain = () => {
  if (lancerBattleDrainTimer) clearInterval(lancerBattleDrainTimer);
  lancerBattleDrainTimer = setInterval(
    tickLancerBattleDrain,
    LANCER_BATTLE_DRAIN_INTERVAL_MS
  );
};

const enterLancerBattleClash = () => {
  if (lancerBattleState !== LANCER_BATTLE_STAGES.intro) return;
  lancerBattleState = LANCER_BATTLE_STAGES.active;
  lancerBattleProgressValue = LANCER_BATTLE_START_PROGRESS;
  updateLancerBattleProgress();
  lancerBattleWindow?.classList.add("is-clashing");
  if (lancerBattlePush) {
    lancerBattlePush.disabled = false;
    lancerBattlePush.focus({ preventScroll: true });
  }
  setLancerBattleStatus("Fight back through the Lancer lock!");
  startLancerBattleBoomerang();
  startLancerBattleDrain();
};

const scheduleLancerBattleClash = () => {
  if (lancerBattleClashTimer) clearTimeout(lancerBattleClashTimer);
  const durationMs =
    lancerBattleClashVideo && Number.isFinite(lancerBattleClashVideo.duration)
      ? Math.max(
          800,
          (
            lancerBattleClashVideo.duration -
            LANCER_BATTLE_BOOMERANG_SECONDS -
            LANCER_BATTLE_BOOMERANG_START_BUFFER_SECONDS
          ) * 1000
        )
      : LANCER_BATTLE_FALLBACK_CLASH_MS;
  lancerBattleClashTimer = setTimeout(() => {
    lancerBattleClashTimer = null;
    enterLancerBattleClash();
  }, durationMs);
};

const startLancerBattle = () => {
  if (lancerBattleState !== LANCER_BATTLE_STAGES.ready) return;
  lancerBattleState = LANCER_BATTLE_STAGES.intro;
  if (lancerBattleTitle) lancerBattleTitle.textContent = "Chainsaw Clash";
  showLancerBattleStage("clash");
  setLancerBattleStatus("The blades are biting...");
  if (lancerBattlePush) {
    lancerBattlePush.disabled = true;
  }
  loadDeferredMedia(lancerBattleWindow);
  if (lancerBattleClashVideo) {
    lancerBattleClashVideo.currentTime = 0;
    const playRequest = lancerBattleClashVideo.play();
    if (playRequest && typeof playRequest.catch === "function") {
      playRequest.catch(() => {});
    }
    if (lancerBattleClashVideo.readyState >= 1) {
      scheduleLancerBattleClash();
    } else {
      lancerBattleClashVideo.addEventListener(
        "loadedmetadata",
        scheduleLancerBattleClash,
        { once: true }
      );
      lancerBattleClashTimer = setTimeout(() => {
        lancerBattleClashTimer = null;
        enterLancerBattleClash();
      }, LANCER_BATTLE_FALLBACK_CLASH_MS);
    }
  } else {
    lancerBattleClashTimer = setTimeout(
      enterLancerBattleClash,
      LANCER_BATTLE_FALLBACK_CLASH_MS
    );
  }
};

const pushLancerBattle = () => {
  if (lancerBattleState !== LANCER_BATTLE_STAGES.active) return;
  lancerBattleProgressValue = Math.min(
    100,
    lancerBattleProgressValue + LANCER_BATTLE_PUSH_GAIN
  );
  updateLancerBattleProgress();
  setLancerBattleStatus("Keep fighting back!");
  pulseLancerBattleWindow();
  if (lancerBattleProgressValue >= 100) finishLancerBattle(true);
};

const handleLancerBattleKeyMash = (event) => {
  if (lancerBattleState !== LANCER_BATTLE_STAGES.active) return;
  if (event.repeat || event.metaKey || event.ctrlKey || event.altKey) return;
  event.preventDefault();
  pushLancerBattle();
};

const showLancerBattleWindow = () => {
  if (!lancerBattleWindow) return;
  if (isLancerBattleVisible()) {
    lancerBattleWindow.style.zIndex = String(topZ++);
    clampRandomEventWindowToViewport(lancerBattleWindow);
    return;
  }
  resetLancerBattleWindow();
  loadDeferredMedia(lancerBattleWindow);
  lancerBattleWindow.classList.remove("is-hidden", "is-closing");
  lancerBattleWindow.setAttribute("aria-hidden", "false");
  positionRandomEventWindowInViewport(lancerBattleWindow);
  clampRandomEventWindowAfterMediaLoad(lancerBattleWindow);
  lancerBattleWindow.style.zIndex = String(topZ++);
  restartWindowAnimation(lancerBattleWindow, "is-opening");
  requestAnimationFrame(() => {
    lancerBattleStart?.focus({ preventScroll: true });
  });
};

const closeLancerBattleWindow = () => {
  if (!lancerBattleWindow || lancerBattleWindow.classList.contains("is-hidden")) return;
  lancerBattleOpenFinalAfterClose = false;
  clearLancerBattleTimers();
  clearLancerBattleVideo();
  clearLancerBattleResultMedia();
  lancerBattleState = LANCER_BATTLE_STAGES.idle;
  lancerBattleWindow.setAttribute("aria-hidden", "true");
  restartWindowAnimation(lancerBattleWindow, "is-closing");
};

const brandBurnsRandomInt = (min, max) =>
  Math.floor(Math.random() * (max - min + 1)) + min;

const shuffleBrandBurnsItems = (items) => {
  const shuffled = [...items];
  for (let index = shuffled.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(Math.random() * (index + 1));
    [shuffled[index], shuffled[swapIndex]] = [shuffled[swapIndex], shuffled[index]];
  }
  return shuffled;
};

const isBrandBurnsWindowVisible = (win) =>
  Boolean(
    win &&
      !win.classList.contains("is-hidden") &&
      win.getAttribute("aria-hidden") === "false"
  );

const isBrandBurnsMainWindowVisible = () =>
  isBrandBurnsWindowVisible(brandBurnsWindow);

const isBrandBurnsEnemyWindowVisible = (win) =>
  isBrandBurnsWindowVisible(win);

const isBrandBurnsButtonClickTarget = (target) =>
  Boolean(
    target?.closest("button") &&
      target.closest(
        "#brand-burns-window, .brand-apostle-window, .brand-puck-window, .brand-block-window"
      )
  );

const isBrandBurnsVisible = () =>
  isBrandBurnsMainWindowVisible() ||
  isBrandBurnsPuckWindowVisible() ||
  isBrandBurnsBlockWindowVisible() ||
  brandBurnsEnemyWindows.some(isBrandBurnsEnemyWindowVisible);

const setBrandBurnsStageHidden = (stage, hidden) => {
  if (!stage) return;
  stage.classList.toggle("is-hidden", hidden);
};

const brandBurnsMeterPercent = (value, maxValue) => {
  const max = Math.max(1, maxValue);
  const clamped = Math.max(0, Math.min(max, value));
  if (clamped <= 0) return 0;
  const segments = Math.ceil((clamped / max) * BRAND_BURNS_METER_SEGMENTS);
  return (
    (Math.min(BRAND_BURNS_METER_SEGMENTS, segments) / BRAND_BURNS_METER_SEGMENTS) * 100
  );
};

const updateBrandBurnsHud = () => {
  const maxHealth = Math.max(1, brandBurnsStats.maxHealth || BRAND_BURNS_PLAYER_MAX_HEALTH);
  const health = Math.max(0, Math.min(maxHealth, brandBurnsStats.health));
  const healthPercent = brandBurnsMeterPercent(health, maxHealth);
  const stamina = Math.max(0, Math.min(BRAND_BURNS_PLAYER_MAX_STAMINA, brandBurnsStats.stamina));
  const staminaPercent = brandBurnsMeterPercent(stamina, BRAND_BURNS_PLAYER_MAX_STAMINA);
  const remaining = Math.max(0, brandBurnsStats.total - brandBurnsStats.defeated);

  if (brandBurnsHealth) brandBurnsHealth.style.width = `${healthPercent}%`;
  if (brandBurnsHealth?.parentElement) {
    brandBurnsHealth.parentElement.setAttribute("aria-valuenow", Math.round(health));
    brandBurnsHealth.parentElement.setAttribute("aria-valuemax", String(maxHealth));
  }
  if (brandBurnsHealthValue) {
    brandBurnsHealthValue.textContent = `${Math.round(health)}/${maxHealth}`;
  }
  if (brandBurnsStamina) brandBurnsStamina.style.width = `${staminaPercent}%`;
  if (brandBurnsStamina?.parentElement) {
    brandBurnsStamina.parentElement.setAttribute("aria-valuenow", Math.round(stamina));
    brandBurnsStamina.parentElement.setAttribute(
      "aria-valuemax",
      String(BRAND_BURNS_PLAYER_MAX_STAMINA)
    );
  }
  if (brandBurnsStaminaValue) {
    brandBurnsStaminaValue.textContent = `${Math.round(stamina)}/${BRAND_BURNS_PLAYER_MAX_STAMINA}`;
  }
  if (brandBurnsEnemyCount) {
    brandBurnsEnemyCount.textContent = `Apostles remaining: ${remaining}`;
  }
};

const resetBrandBurnsStats = () => {
  brandBurnsStats = {
    health: BRAND_BURNS_PLAYER_MAX_HEALTH,
    maxHealth: BRAND_BURNS_PLAYER_MAX_HEALTH,
    stamina: BRAND_BURNS_PLAYER_MAX_STAMINA,
    defeated: 0,
    total: BRAND_BURNS_ENCOUNTER_COUNT,
  };
  updateBrandBurnsHud();
};

const stopBrandBurnsStaminaRecovery = () => {
  if (!brandBurnsStaminaTimer) return;
  clearInterval(brandBurnsStaminaTimer);
  brandBurnsStaminaTimer = null;
};

const hasBrandBurnsAttackStamina = () =>
  brandBurnsStats.stamina >= BRAND_BURNS_STAMINA_ATTACK_MIN_COST;

const getBrandBurnsAttackStaminaCost = () =>
  brandBurnsRandomInt(
    BRAND_BURNS_STAMINA_ATTACK_MIN_COST,
    Math.min(
      BRAND_BURNS_STAMINA_ATTACK_MAX_COST,
      Math.max(BRAND_BURNS_STAMINA_ATTACK_MIN_COST, Math.floor(brandBurnsStats.stamina))
    )
  );

const getBrandBurnsStaminaRecoveryAmount = () => {
  const maxHealth = Math.max(1, brandBurnsStats.maxHealth || BRAND_BURNS_PLAYER_MAX_HEALTH);
  const staminaFactor = Math.max(
    BRAND_BURNS_STAMINA_RECOVERY_MIN_FACTOR,
    Math.max(0, Math.min(BRAND_BURNS_PLAYER_MAX_STAMINA, brandBurnsStats.stamina)) /
      BRAND_BURNS_PLAYER_MAX_STAMINA
  );
  const missingHealthFactor =
    1 +
    (1 - Math.max(0, Math.min(maxHealth, brandBurnsStats.health)) / maxHealth) *
      BRAND_BURNS_STAMINA_LOW_HEALTH_BONUS;
  const blockFactor = brandBurnsBlocking ? BRAND_BURNS_STAMINA_BLOCK_RECOVERY_BONUS : 1;

  return BRAND_BURNS_STAMINA_RECOVERY_AMOUNT * staminaFactor * missingHealthFactor * blockFactor;
};

const startBrandBurnsStaminaRecovery = () => {
  stopBrandBurnsStaminaRecovery();
  brandBurnsStaminaTimer = setInterval(() => {
    if (brandBurnsStage !== "fight") {
      stopBrandBurnsStaminaRecovery();
      return;
    }
    const nextStamina = Math.min(
      BRAND_BURNS_PLAYER_MAX_STAMINA,
      brandBurnsStats.stamina + getBrandBurnsStaminaRecoveryAmount()
    );
    if (nextStamina === brandBurnsStats.stamina) return;

    brandBurnsStats.stamina = nextStamina;
    updateBrandBurnsHud();
    updateBrandBurnsAttackButtonStates();
  }, BRAND_BURNS_STAMINA_RECOVERY_MS);
};

const clearBrandBurnsEnemyTimers = () => {
  brandBurnsEnemyTimers.forEach((timer) => clearTimeout(timer));
  brandBurnsEnemyTimers = [];
};

const updateBrandBurnsEnemyHud = (state) => {
  const percent = Math.max(0, Math.min(100, (state.health / state.maxHealth) * 100));
  if (state.healthBar) state.healthBar.style.width = `${percent}%`;
  if (state.healthValue) {
    state.healthValue.textContent = `${Math.max(0, Math.round(state.health))}/${state.maxHealth}`;
  }
};

const brandBurnsViewerImage = () => brandBurnsWindow?.querySelector("#brand-burns-weapon-icon");

const setBrandBurnsViewerImage = (src) => {
  const image = brandBurnsViewerImage();
  if (!image) return;
  image.dataset.src = src;
  image.src = src;
};

const clearBrandBurnsEnemyAttackTimer = (state) => {
  if (!state?.playerAttackTimer) return;
  clearTimeout(state.playerAttackTimer);
  state.playerAttackTimer = null;
};

const brandBurnsOmenLightningCanvas = () =>
  brandBurnsWindow?.querySelector(".brand-burns-lightning-canvas") || null;

const clearBrandBurnsOmenEffect = () => {
  if (brandBurnsOmenTimer) {
    clearTimeout(brandBurnsOmenTimer);
    brandBurnsOmenTimer = null;
  }
  if (brandBurnsOmenHitTimer) {
    clearTimeout(brandBurnsOmenHitTimer);
    brandBurnsOmenHitTimer = null;
  }
  if (brandBurnsOmenLightningFrame) {
    cancelAnimationFrame(brandBurnsOmenLightningFrame);
    brandBurnsOmenLightningFrame = null;
  }
  clearLightningCanvas(brandBurnsOmenLightningCanvas());
  if (brandBurnsWindow) brandBurnsWindow.classList.remove("is-omen");
};

const clearBrandBurnsHealEffect = () => {
  if (brandBurnsHealHitTimer) {
    clearTimeout(brandBurnsHealHitTimer);
    brandBurnsHealHitTimer = null;
  }
  if (brandBurnsHealLightningFrame) {
    cancelAnimationFrame(brandBurnsHealLightningFrame);
    brandBurnsHealLightningFrame = null;
  }
  clearLightningCanvas(brandBurnsOmenLightningCanvas());
  if (brandBurnsWindow) brandBurnsWindow.classList.remove("is-healed");
};

const startBrandBurnsOmenLightningStrike = () => {
  const canvas = brandBurnsOmenLightningCanvas();
  if (!canvas) return;
  if (brandBurnsOmenLightningFrame) {
    cancelAnimationFrame(brandBurnsOmenLightningFrame);
  }
  const startedAt = performance.now();

  const render = (now) => {
    const progress = Math.min(1, (now - startedAt) / FATE_LIGHTNING_DURATION_MS);
    const flicker = progress < 0.16 ? 1 : Math.random() > 0.32 ? 1 - progress * 0.42 : 0.18;
    const alpha = Math.max(0, flicker * (1 - progress * 0.36));
    drawLightningBorderFrame(canvas, alpha);

    if (progress < 1) {
      brandBurnsOmenLightningFrame = requestAnimationFrame(render);
      return;
    }

    brandBurnsOmenLightningFrame = null;
    clearLightningCanvas(canvas);
  };

  brandBurnsOmenLightningFrame = requestAnimationFrame(render);
};

const pulseBrandBurnsOmen = () => {
  if (!brandBurnsWindow || brandBurnsStage !== "prompt" || !isBrandBurnsMainWindowVisible()) {
    return;
  }
  if (brandBurnsOmenHitTimer) {
    clearTimeout(brandBurnsOmenHitTimer);
    brandBurnsOmenHitTimer = null;
  }

  brandBurnsWindow.classList.remove("is-omen");
  void brandBurnsWindow.offsetWidth;
  brandBurnsWindow.classList.add("is-omen");
  startBrandBurnsOmenLightningStrike();
  brandBurnsOmenHitTimer = setTimeout(() => {
    if (brandBurnsWindow) brandBurnsWindow.classList.remove("is-omen");
    brandBurnsOmenHitTimer = null;
  }, 240);
};

const scheduleBrandBurnsOmenPulse = () => {
  if (brandBurnsOmenTimer) {
    clearTimeout(brandBurnsOmenTimer);
    brandBurnsOmenTimer = null;
  }
  if (!brandBurnsWindow || brandBurnsStage !== "prompt" || !isBrandBurnsMainWindowVisible()) {
    return;
  }

  const delay = brandBurnsRandomInt(
    BRAND_BURNS_OMEN_MIN_DELAY_MS,
    BRAND_BURNS_OMEN_MAX_DELAY_MS
  );
  brandBurnsOmenTimer = setTimeout(() => {
    brandBurnsOmenTimer = null;
    if (brandBurnsStage !== "prompt" || !isBrandBurnsMainWindowVisible()) return;
    pulseBrandBurnsOmen();
    scheduleBrandBurnsOmenPulse();
  }, delay);
};

const startBrandBurnsHealLightningStrike = () => {
  const canvas = brandBurnsOmenLightningCanvas();
  if (!canvas) return;
  if (brandBurnsHealLightningFrame) cancelAnimationFrame(brandBurnsHealLightningFrame);
  const startedAt = performance.now();

  const render = (now) => {
    const progress = Math.min(1, (now - startedAt) / FATE_LIGHTNING_DURATION_MS);
    const flicker = progress < 0.16 ? 1 : Math.random() > 0.32 ? 1 - progress * 0.42 : 0.18;
    const alpha = Math.max(0, flicker * (1 - progress * 0.36));
    drawLightningBorderFrame(canvas, alpha, GREEN_LIGHTNING_PALETTE);

    if (progress < 1) {
      brandBurnsHealLightningFrame = requestAnimationFrame(render);
      return;
    }

    brandBurnsHealLightningFrame = null;
    clearLightningCanvas(canvas);
  };

  brandBurnsHealLightningFrame = requestAnimationFrame(render);
};

const pulseBrandBurnsHealEffect = () => {
  if (!brandBurnsWindow) return;
  if (brandBurnsHealHitTimer) {
    clearTimeout(brandBurnsHealHitTimer);
    brandBurnsHealHitTimer = null;
  }

  brandBurnsWindow.classList.remove("is-healed");
  void brandBurnsWindow.offsetWidth;
  brandBurnsWindow.classList.add("is-healed");
  startBrandBurnsHealLightningStrike();
  brandBurnsHealHitTimer = setTimeout(() => {
    if (brandBurnsWindow) brandBurnsWindow.classList.remove("is-healed");
    brandBurnsHealHitTimer = null;
  }, 240);
};

const isBrandBurnsPuckWindowVisible = () =>
  isBrandBurnsWindowVisible(brandBurnsPuckWindow);

const clearBrandBurnsPuckCooldown = () => {
  if (!brandBurnsPuckCooldownTimer) return;
  clearTimeout(brandBurnsPuckCooldownTimer);
  brandBurnsPuckCooldownTimer = null;
};

const setBrandBurnsPuckHealReady = (ready) => {
  brandBurnsPuckHealReady = ready;
  if (!brandBurnsPuckHealButton) return;
  const canHeal = ready && brandBurnsStage === "fight" && brandBurnsStats.health > 0;
  brandBurnsPuckHealButton.disabled = !canHeal;
};

const createBrandBurnsStatusEntry = (...nodes) => {
  const entry = document.createElement("span");
  entry.className = "brand-burns-status-entry";
  entry.append(...nodes);
  return entry;
};

const scrollBrandBurnsStatusLog = () => {
  if (!brandBurnsStatus) return;
  brandBurnsStatus.scrollTop = brandBurnsStatus.scrollHeight;
};

const setBrandBurnsStatusText = (message) => {
  if (!brandBurnsStatus) return;
  brandBurnsStatus.replaceChildren(createBrandBurnsStatusEntry(document.createTextNode(message)));
  scrollBrandBurnsStatusLog();
};

const appendBrandBurnsStatusWithAmount = (prefix, amount, suffix, amountClassName) => {
  if (!brandBurnsStatus) return;
  const amountNode = document.createElement("span");
  amountNode.className = amountClassName;
  amountNode.textContent = String(amount);
  const entry = createBrandBurnsStatusEntry(
    document.createTextNode(prefix),
    amountNode,
    document.createTextNode(suffix)
  );
  entry.classList.add("is-new");
  brandBurnsStatus.append(entry);

  while (brandBurnsStatus.children.length > 4) {
    brandBurnsStatus.firstElementChild?.remove();
  }

  scrollBrandBurnsStatusLog();
};

const scheduleBrandBurnsPuckHealCooldown = () => {
  clearBrandBurnsPuckCooldown();
  setBrandBurnsPuckHealReady(false);
  brandBurnsPuckCooldownTimer = setTimeout(() => {
    brandBurnsPuckCooldownTimer = null;
    setBrandBurnsPuckHealReady(true);
  }, BRAND_BURNS_PUCK_HEAL_COOLDOWN_MS);
};

const getBrandBurnsRemainingApostleCount = () =>
  Math.max(0, brandBurnsStats.total - brandBurnsStats.defeated);

const getBrandBurnsPuckHealRange = () =>
  BRAND_BURNS_PUCK_HEAL_RANGES_BY_REMAINING[getBrandBurnsRemainingApostleCount()] ||
  BRAND_BURNS_PUCK_HEAL_RANGES_BY_REMAINING[1];

const healBrandBurnsPlayerFromPuck = () => {
  if (!brandBurnsPuckHealReady || brandBurnsStage !== "fight" || brandBurnsStats.health <= 0) {
    return;
  }

  const maxHealth = Math.max(1, brandBurnsStats.maxHealth || BRAND_BURNS_PLAYER_MAX_HEALTH);
  const [healMin, healMax] = getBrandBurnsPuckHealRange();
  const healAmount = brandBurnsRandomInt(healMin, healMax);
  const previousHealth = brandBurnsStats.health;
  brandBurnsStats.health = Math.min(maxHealth, brandBurnsStats.health + healAmount);
  const actualHeal = Math.round(brandBurnsStats.health - previousHealth);

  updateBrandBurnsHud();
  pulseBrandBurnsHealEffect();
  if (actualHeal > 0) {
    appendBrandBurnsStatusWithAmount(
      "Puck heals you for ",
      actualHeal,
      ".",
      "brand-burns-status-heal"
    );
  } else {
    setBrandBurnsStatusText("Puck is ready if the brand burns again.");
  }
  scheduleBrandBurnsPuckHealCooldown();
};

const removeBrandBurnsPuckWindow = () => {
  clearBrandBurnsPuckCooldown();
  if (brandBurnsPuckWindow) brandBurnsPuckWindow.remove();
  brandBurnsPuckWindow = null;
  brandBurnsPuckHealButton = null;
  brandBurnsPuckHealReady = false;
};

const closeBrandBurnsPuckWindow = () => {
  if (!brandBurnsPuckWindow) return;
  clearBrandBurnsPuckCooldown();
  if (brandBurnsPuckWindow.classList.contains("is-hidden")) {
    removeBrandBurnsPuckWindow();
    return;
  }
  brandBurnsPuckWindow.setAttribute("aria-hidden", "true");
  restartWindowAnimation(brandBurnsPuckWindow, "is-closing");
};

const createBrandBurnsPuckWindow = () => {
  const win = document.createElement("div");
  win.className = "window brand-puck-window is-hidden";
  win.setAttribute("aria-hidden", "true");

  const titleBar = document.createElement("div");
  titleBar.className = "title-bar";

  const title = document.createElement("div");
  title.className = "title-bar-text";
  title.textContent = "Puck";
  titleBar.append(title);

  const body = document.createElement("div");
  body.className = "window-body brand-puck-body";

  const frame = document.createElement("div");
  frame.className = "brand-puck-image-frame";

  const image = document.createElement("img");
  image.src = BRAND_BURNS_PUCK_IMAGE;
  image.decoding = "async";
  image.alt = "Puck";
  frame.append(image);

  const actions = document.createElement("div");
  actions.className = "brand-puck-actions";

  const healButton = document.createElement("button");
  healButton.type = "button";
  healButton.textContent = "Heal";
  actions.append(healButton);
  body.append(frame, actions);
  win.append(titleBar, body);

  brandBurnsPuckHealButton = healButton;

  healButton.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    healBrandBurnsPlayerFromPuck();
  });

  win.addEventListener("click", (event) => {
    event.stopPropagation();
  });

  win.addEventListener("animationend", (event) => {
    if (event.target !== win) return;
    if (event.animationName === "retro-window-open") {
      win.classList.remove("is-opening");
      clampRandomEventWindowToViewport(win);
      return;
    }
    if (event.animationName === "retro-window-close") {
      removeBrandBurnsPuckWindow();
    }
  });

  image.addEventListener("load", () => clampRandomEventWindowToViewport(win));
  return win;
};

const showBrandBurnsPuckWindow = () => {
  if (isBrandBurnsPuckWindowVisible()) {
    brandBurnsPuckWindow.style.zIndex = String(topZ++);
    clampRandomEventWindowToViewport(brandBurnsPuckWindow);
    setBrandBurnsPuckHealReady(brandBurnsPuckHealReady);
    return;
  }

  brandBurnsPuckWindow = createBrandBurnsPuckWindow();
  document.body.appendChild(brandBurnsPuckWindow);
  brandBurnsPuckWindow.classList.remove("is-hidden", "is-closing");
  brandBurnsPuckWindow.setAttribute("aria-hidden", "false");
  positionRandomEventWindowInViewport(brandBurnsPuckWindow);
  brandBurnsPuckWindow.style.zIndex = String(topZ++);
  restartWindowAnimation(brandBurnsPuckWindow, "is-opening");
  clampRandomEventWindowAfterMediaLoad(brandBurnsPuckWindow);
  setBrandBurnsPuckHealReady(true);
};

const maybeShowBrandBurnsPuckWindow = () => {
  const maxHealth = Math.max(1, brandBurnsStats.maxHealth || BRAND_BURNS_PLAYER_MAX_HEALTH);
  const isBelowThreshold =
    brandBurnsStats.health > 0 &&
    brandBurnsStats.health < maxHealth * BRAND_BURNS_PUCK_HEALTH_THRESHOLD_FACTOR;

  if (
    brandBurnsPuckHasAppeared ||
    brandBurnsStage !== "fight" ||
    !isBrandBurnsMainWindowVisible() ||
    !isBelowThreshold
  ) {
    return;
  }

  brandBurnsPuckHasAppeared = true;
  showBrandBurnsPuckWindow();
};

const clearBrandBurnsEnemyHitEffect = (state) => {
  if (!state) return;
  if (state.hitTimer) {
    clearTimeout(state.hitTimer);
    state.hitTimer = null;
  }
  if (state.lightningFrame) {
    cancelAnimationFrame(state.lightningFrame);
    state.lightningFrame = null;
  }
  clearLightningCanvas(state.lightningCanvas);
  if (state.win) state.win.classList.remove("is-hit");
};

const startBrandBurnsEnemyLightningStrike = (state) => {
  if (!state?.lightningCanvas) return;
  if (state.lightningFrame) cancelAnimationFrame(state.lightningFrame);
  const startedAt = performance.now();

  const render = (now) => {
    const progress = Math.min(1, (now - startedAt) / FATE_LIGHTNING_DURATION_MS);
    const flicker = progress < 0.16 ? 1 : Math.random() > 0.32 ? 1 - progress * 0.42 : 0.18;
    const alpha = Math.max(0, flicker * (1 - progress * 0.36));
    drawLightningBorderFrame(state.lightningCanvas, alpha);

    if (progress < 1) {
      state.lightningFrame = requestAnimationFrame(render);
      return;
    }

    state.lightningFrame = null;
    clearLightningCanvas(state.lightningCanvas);
  };

  state.lightningFrame = requestAnimationFrame(render);
};

const pulseBrandBurnsEnemyHit = (state) => {
  if (!state?.win) return;
  if (state.hitTimer) {
    clearTimeout(state.hitTimer);
    state.hitTimer = null;
  }

  state.win.classList.remove("is-hit");
  void state.win.offsetWidth;
  state.win.classList.add("is-hit");
  startBrandBurnsEnemyLightningStrike(state);
  state.hitTimer = setTimeout(() => {
    if (state.win) state.win.classList.remove("is-hit");
    state.hitTimer = null;
  }, 240);
};

const stopBrandBurnsEnemyAttacks = () => {
  brandBurnsEnemyWindows.forEach((win) => {
    if (win.brandBurnsState) clearBrandBurnsEnemyAttackTimer(win.brandBurnsState);
  });
};

const updateBrandBurnsAttackButtonStates = () => {
  const shouldDisableAttacks =
    brandBurnsBlocking ||
    brandBurnsStage !== "fight" ||
    brandBurnsStats.health <= 0 ||
    !hasBrandBurnsAttackStamina();

  brandBurnsEnemyWindows.forEach((win) => {
    const state = win.brandBurnsState;
    if (!state?.attackButton) return;
    state.attackButton.disabled = state.defeated || shouldDisableAttacks;
  });
};

const isBrandBurnsBlockCoolingDown = () => Boolean(brandBurnsBlockCooldownTimer);

const updateBrandBurnsActionButton = () => {
  if (!brandBurnsFight) return;
  if (brandBurnsOutcome === "won") {
    brandBurnsFight.textContent = "Rest";
    brandBurnsFight.disabled = false;
    return;
  }
  if (brandBurnsOutcome === "lost") {
    brandBurnsFight.textContent = "Give Up";
    brandBurnsFight.disabled = false;
    return;
  }
  if (brandBurnsStage === "prompt") {
    brandBurnsFight.textContent = "Fight them off!";
    brandBurnsFight.disabled = false;
    return;
  }
  if (brandBurnsStage === "fight") {
    if (brandBurnsBlocking) {
      brandBurnsFight.textContent = "Blocking...";
      brandBurnsFight.disabled = true;
      return;
    }
    if (isBrandBurnsBlockCoolingDown()) {
      brandBurnsFight.textContent = "Recovering...";
      brandBurnsFight.disabled = true;
      return;
    }
    brandBurnsFight.textContent = "Block";
    brandBurnsFight.disabled = brandBurnsStats.health <= 0;
    return;
  }
  brandBurnsFight.textContent = "Block";
  brandBurnsFight.disabled = true;
};

const clearBrandBurnsBlockCooldown = () => {
  if (!brandBurnsBlockCooldownTimer) return;
  clearTimeout(brandBurnsBlockCooldownTimer);
  brandBurnsBlockCooldownTimer = null;
};

const startBrandBurnsBlockCooldown = () => {
  clearBrandBurnsBlockCooldown();
  if (brandBurnsStage !== "fight" || brandBurnsStats.health <= 0 || brandBurnsOutcome) return;
  brandBurnsBlockCooldownTimer = setTimeout(() => {
    brandBurnsBlockCooldownTimer = null;
    updateBrandBurnsActionButton();
  }, BRAND_BURNS_BLOCK_COOLDOWN_MS);
  updateBrandBurnsActionButton();
};

const clearBrandBurnsBlockProgress = () => {
  if (!brandBurnsBlockProgressFrame) return;
  cancelAnimationFrame(brandBurnsBlockProgressFrame);
  brandBurnsBlockProgressFrame = null;
};

const isBrandBurnsBlockWindowVisible = () =>
  isBrandBurnsWindowVisible(brandBurnsBlockWindow);

const removeBrandBurnsBlockWindow = () => {
  clearBrandBurnsBlockProgress();
  if (brandBurnsBlockWindow) brandBurnsBlockWindow.remove();
  brandBurnsBlockWindow = null;
  brandBurnsBlockProgressBar = null;
};

const closeBrandBurnsBlockWindow = () => {
  clearBrandBurnsBlockProgress();
  if (!brandBurnsBlockWindow) return;
  if (brandBurnsBlockWindow.classList.contains("is-hidden")) {
    removeBrandBurnsBlockWindow();
    return;
  }
  const closingWindow = brandBurnsBlockWindow;
  brandBurnsBlockWindow.setAttribute("aria-hidden", "true");
  restartWindowAnimation(brandBurnsBlockWindow, "is-closing");
  setTimeout(() => {
    if (brandBurnsBlockWindow === closingWindow && closingWindow.classList.contains("is-closing")) {
      removeBrandBurnsBlockWindow();
    }
  }, 220);
};

const animateBrandBurnsBlockProgress = (startedAt) => {
  if (!brandBurnsBlockProgressBar || !brandBurnsBlocking) {
    clearBrandBurnsBlockProgress();
    return;
  }

  const progress = Math.min(1, (performance.now() - startedAt) / BRAND_BURNS_BLOCK_DURATION_MS);
  const percent = progress * 100;
  brandBurnsBlockProgressBar.style.width = `${percent}%`;
  brandBurnsBlockProgressBar.parentElement?.setAttribute(
    "aria-valuenow",
    String(Math.round(percent))
  );

  if (progress >= 1) {
    brandBurnsBlockProgressFrame = null;
    endBrandBurnsBlock();
    return;
  }

  brandBurnsBlockProgressFrame = requestAnimationFrame(() =>
    animateBrandBurnsBlockProgress(startedAt)
  );
};

const createBrandBurnsBlockWindow = () => {
  const win = document.createElement("div");
  win.className = "window brand-block-window is-hidden";
  win.setAttribute("aria-hidden", "true");

  const titleBar = document.createElement("div");
  titleBar.className = "title-bar";

  const title = document.createElement("div");
  title.className = "title-bar-text";
  title.textContent = "Blocking";
  titleBar.append(title);

  const body = document.createElement("div");
  body.className = "window-body brand-block-body";

  const label = document.createElement("p");
  label.className = "brand-block-status";
  label.textContent = "Blocking";

  const progress = document.createElement("div");
  progress.className = "progress-indicator segmented brand-block-progress";
  progress.setAttribute("role", "progressbar");
  progress.setAttribute("aria-label", "Block duration");
  progress.setAttribute("aria-valuemin", "0");
  progress.setAttribute("aria-valuemax", "100");
  progress.setAttribute("aria-valuenow", "0");

  const bar = document.createElement("span");
  bar.className = "progress-indicator-bar";
  bar.style.width = "0%";
  progress.append(bar);

  const actions = document.createElement("div");
  actions.className = "brand-block-actions";

  const dropButton = document.createElement("button");
  dropButton.type = "button";
  dropButton.textContent = "Drop Guard";
  actions.append(dropButton);

  body.append(label, progress, actions);
  win.append(titleBar, body);

  dropButton.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    endBrandBurnsBlock();
  });

  win.addEventListener("click", (event) => {
    event.stopPropagation();
  });

  win.addEventListener("animationend", (event) => {
    if (event.target !== win) return;
    if (event.animationName === "retro-window-open") {
      win.classList.remove("is-opening");
      clampRandomEventWindowToViewport(win);
      return;
    }
    if (event.animationName === "retro-window-close") {
      removeBrandBurnsBlockWindow();
    }
  });

  brandBurnsBlockProgressBar = bar;
  return win;
};

const showBrandBurnsBlockWindow = () => {
  removeBrandBurnsBlockWindow();
  brandBurnsBlockWindow = createBrandBurnsBlockWindow();
  document.body.appendChild(brandBurnsBlockWindow);
  brandBurnsBlockWindow.classList.remove("is-hidden", "is-closing");
  brandBurnsBlockWindow.setAttribute("aria-hidden", "false");
  positionRandomEventWindowInViewport(brandBurnsBlockWindow);
  brandBurnsBlockWindow.style.zIndex = String(topZ++);
  restartWindowAnimation(brandBurnsBlockWindow, "is-opening");

  const startedAt = performance.now();
  animateBrandBurnsBlockProgress(startedAt);
};

const endBrandBurnsBlock = () => {
  if (brandBurnsBlockTimer) {
    clearTimeout(brandBurnsBlockTimer);
    brandBurnsBlockTimer = null;
  }
  if (!brandBurnsBlocking) return;
  brandBurnsBlocking = false;
  closeBrandBurnsBlockWindow();
  startBrandBurnsBlockCooldown();
  updateBrandBurnsAttackButtonStates();
  updateBrandBurnsActionButton();
  if (brandBurnsStatus && brandBurnsStage === "fight" && brandBurnsStats.health > 0) {
    setBrandBurnsStatusText("Your guard drops. You can attack again.");
  }
};

const clearBrandBurnsBlock = () => {
  if (brandBurnsBlockTimer) {
    clearTimeout(brandBurnsBlockTimer);
    brandBurnsBlockTimer = null;
  }
  clearBrandBurnsBlockCooldown();
  brandBurnsBlocking = false;
  closeBrandBurnsBlockWindow();
  updateBrandBurnsAttackButtonStates();
  updateBrandBurnsActionButton();
};

const startBrandBurnsBlock = () => {
  if (
    brandBurnsStage !== "fight" ||
    brandBurnsStats.health <= 0 ||
    brandBurnsBlocking ||
    isBrandBurnsBlockCoolingDown()
  ) {
    updateBrandBurnsActionButton();
    return;
  }
  brandBurnsBlocking = true;
  updateBrandBurnsAttackButtonStates();
  updateBrandBurnsActionButton();
  if (brandBurnsStatus) {
    setBrandBurnsStatusText("You brace behind the Dragon Slayer.");
  }
  showBrandBurnsBlockWindow();
  if (brandBurnsBlockTimer) clearTimeout(brandBurnsBlockTimer);
  brandBurnsBlockTimer = setTimeout(endBrandBurnsBlock, BRAND_BURNS_BLOCK_DURATION_MS);
};

const finishBrandBurnsIfPlayerDefeated = () => {
  if (brandBurnsStats.health > 0) return false;
  brandBurnsStats.health = 0;
  brandBurnsOutcome = "lost";
  updateBrandBurnsHud();
  stopBrandBurnsStaminaRecovery();
  stopBrandBurnsEnemyAttacks();
  clearBrandBurnsBlock();
  clearBrandBurnsPuckCooldown();
  setBrandBurnsPuckHealReady(false);
  updateBrandBurnsAttackButtonStates();
  if (brandBurnsStatus) {
    setBrandBurnsStatusText("You have been overwhelmed.");
  }
  updateBrandBurnsActionButton();
  return true;
};

const scheduleBrandBurnsEnemyAttack = (state) => {
  clearBrandBurnsEnemyAttackTimer(state);
  if (
    !state ||
    state.defeated ||
    brandBurnsStage !== "fight" ||
    brandBurnsStats.health <= 0 ||
    !isBrandBurnsEnemyWindowVisible(state.win)
  ) {
    return;
  }

  const delay = brandBurnsRandomInt(
    BRAND_BURNS_APOSTLE_ATTACK_MIN_DELAY_MS,
    BRAND_BURNS_APOSTLE_ATTACK_MAX_DELAY_MS
  );
  state.playerAttackTimer = setTimeout(() => {
    state.playerAttackTimer = null;
    if (
      state.defeated ||
      brandBurnsStage !== "fight" ||
      brandBurnsStats.health <= 0 ||
      !isBrandBurnsEnemyWindowVisible(state.win)
    ) {
      return;
    }

    const rawDamage = brandBurnsRandomInt(
      BRAND_BURNS_APOSTLE_PLAYER_ATTACK_MIN_DAMAGE,
      BRAND_BURNS_APOSTLE_PLAYER_ATTACK_MAX_DAMAGE
    );
    const damage = brandBurnsBlocking
      ? Math.max(1, Math.ceil(rawDamage * BRAND_BURNS_BLOCK_DAMAGE_FACTOR))
      : rawDamage;
    brandBurnsStats.health = Math.max(0, brandBurnsStats.health - damage);
    updateBrandBurnsHud();
    maybeShowBrandBurnsPuckWindow();
    if (brandBurnsWindow) {
      brandBurnsWindow.classList.remove("is-hit");
      void brandBurnsWindow.offsetWidth;
      brandBurnsWindow.classList.add("is-hit");
      setTimeout(() => {
        if (brandBurnsWindow) brandBurnsWindow.classList.remove("is-hit");
      }, 190);
    }
    appendBrandBurnsStatusWithAmount(
      brandBurnsBlocking
        ? `${state.definition.name} hits your guard for `
        : `${state.definition.name} hits you for `,
      damage,
      " damage.",
      "brand-burns-status-damage"
    );
    if (!finishBrandBurnsIfPlayerDefeated()) {
      scheduleBrandBurnsEnemyAttack(state);
    }
  }, delay);
};

const removeBrandBurnsEnemyWindow = (win) => {
  if (!win) return;
  if (win.brandBurnsState) clearBrandBurnsEnemyAttackTimer(win.brandBurnsState);
  if (win.brandBurnsState) clearBrandBurnsEnemyHitEffect(win.brandBurnsState);
  win.remove();
  brandBurnsEnemyWindows = brandBurnsEnemyWindows.filter((item) => item !== win);
};

const closeBrandBurnsEnemyWindow = (win) => {
  if (!win || win.classList.contains("is-closing")) return;
  if (win.brandBurnsState) clearBrandBurnsEnemyAttackTimer(win.brandBurnsState);
  if (win.brandBurnsState) clearBrandBurnsEnemyHitEffect(win.brandBurnsState);
  win.setAttribute("aria-hidden", "true");
  restartWindowAnimation(win, "is-closing");
};

const closeBrandBurnsEnemyWindows = ({ stagger = false } = {}) => {
  const windows = brandBurnsEnemyWindows.filter(isBrandBurnsEnemyWindowVisible);
  if (!stagger) {
    windows.forEach(closeBrandBurnsEnemyWindow);
    return;
  }

  windows.forEach((win, index) => {
    const timer = setTimeout(
      () => closeBrandBurnsEnemyWindow(win),
      index * BRAND_BURNS_APOSTLE_CLOSE_DELAY_MS
    );
    brandBurnsEnemyTimers.push(timer);
  });
};

const finishBrandBurnsIfCleared = () => {
  if (brandBurnsStats.defeated < brandBurnsStats.total) return;
  brandBurnsOutcome = "won";
  stopBrandBurnsStaminaRecovery();
  stopBrandBurnsEnemyAttacks();
  clearBrandBurnsBlock();
  closeBrandBurnsPuckWindow();
  setBrandBurnsViewerImage(BRAND_BURNS_PUCK_WIN_IMAGE);
  if (brandBurnsStatus) {
    setBrandBurnsStatusText("The night relents. The brand cools.");
  }
  if (brandBurnsEnemyCount) {
    brandBurnsEnemyCount.textContent = "Apostles remaining: 0";
  }
  updateBrandBurnsActionButton();
};

const recordBrandBurnsDefeat = (state) => {
  state.defeated = true;
  brandBurnsStats.defeated = Math.min(
    brandBurnsStats.total,
    brandBurnsStats.defeated + 1
  );
  updateBrandBurnsHud();
  if (brandBurnsStatus) {
    setBrandBurnsStatusText(`${state.definition.name} is driven back.`);
  }
  finishBrandBurnsIfCleared();
};

const attackBrandBurnsEnemy = (state) => {
  if (!state || state.defeated || brandBurnsBlocking || brandBurnsStats.health <= 0) return;
  if (!hasBrandBurnsAttackStamina()) {
    updateBrandBurnsAttackButtonStates();
    if (brandBurnsStatus) {
      setBrandBurnsStatusText("You need more stamina to attack.");
    }
    return;
  }

  const damage = brandBurnsRandomInt(
    BRAND_BURNS_ATTACK_MIN_DAMAGE,
    BRAND_BURNS_ATTACK_MAX_DAMAGE
  );
  const staminaCost = getBrandBurnsAttackStaminaCost();

  brandBurnsStats.stamina = Math.max(0, brandBurnsStats.stamina - staminaCost);
  state.health = Math.max(0, state.health - damage);
  updateBrandBurnsHud();
  updateBrandBurnsAttackButtonStates();
  updateBrandBurnsEnemyHud(state);

  if (state.damageLabel) {
    state.damageLabel.textContent = `-${damage}`;
    state.damageLabel.classList.remove("is-flashing");
    void state.damageLabel.offsetWidth;
    state.damageLabel.classList.add("is-flashing");
  }

  pulseBrandBurnsEnemyHit(state);

  if (state.health > 0) {
    if (brandBurnsStatus) {
      setBrandBurnsStatusText(`${state.definition.name} takes ${damage} damage.`);
    }
    return;
  }

  if (state.attackButton) {
    state.attackButton.disabled = true;
    state.attackButton.textContent = "Defeated";
  }
  clearBrandBurnsEnemyAttackTimer(state);
  if (state.win) state.win.classList.add("is-defeated");
  recordBrandBurnsDefeat(state);
  setTimeout(() => closeBrandBurnsEnemyWindow(state.win), 650);
};

const createBrandBurnsEnemyWindow = (definition) => {
  const maxHealth = brandBurnsRandomInt(definition.minHealth, definition.maxHealth);
  const state = {
    definition,
    health: maxHealth,
    maxHealth,
    defeated: false,
  };

  const win = document.createElement("div");
  win.className = "window brand-apostle-window is-hidden";
  win.setAttribute("aria-hidden", "true");
  win.dataset.brandBurnsEnemy = definition.id;

  const lightningField = document.createElement("div");
  lightningField.className = "brand-apostle-lightning-field";
  lightningField.setAttribute("aria-hidden", "true");

  const lightningCanvas = document.createElement("canvas");
  lightningCanvas.className = "brand-apostle-lightning-canvas";
  lightningField.append(lightningCanvas);

  const titleBar = document.createElement("div");
  titleBar.className = "title-bar";

  const title = document.createElement("div");
  title.className = "title-bar-text";
  title.textContent = definition.name;

  titleBar.append(title);

  const body = document.createElement("div");
  body.className = "window-body";

  const frame = document.createElement("div");
  frame.className = "brand-apostle-image-frame";

  const image = document.createElement("img");
  image.src = definition.image;
  image.decoding = "async";
  image.alt = `Released form of ${definition.name}`;
  frame.append(image);

  const healthRow = document.createElement("div");
  healthRow.className = "brand-apostle-health-row";

  const healthLabel = document.createElement("div");
  healthLabel.className = "brand-apostle-health-label";

  const healthName = document.createElement("span");
  healthName.textContent = "Health";

  const healthValue = document.createElement("span");
  healthValue.textContent = `${maxHealth}/${maxHealth}`;

  const healthTrack = document.createElement("div");
  healthTrack.className = "brand-apostle-health-track";

  const healthBar = document.createElement("span");
  healthTrack.append(healthBar);

  healthLabel.append(healthName, healthValue);
  healthRow.append(healthLabel, healthTrack);

  const combatRow = document.createElement("div");
  combatRow.className = "brand-apostle-combat-row";

  const damageLabel = document.createElement("span");
  damageLabel.className = "brand-apostle-damage";
  damageLabel.textContent = "-0";

  const attackButton = document.createElement("button");
  attackButton.type = "button";
  attackButton.textContent = "Attack!";

  combatRow.append(damageLabel, attackButton);
  body.append(frame, healthRow, combatRow);
  win.append(lightningField, titleBar, body);

  state.win = win;
  state.healthBar = healthBar;
  state.healthValue = healthValue;
  state.attackButton = attackButton;
  state.damageLabel = damageLabel;
  state.lightningCanvas = lightningCanvas;
  win.brandBurnsState = state;

  attackButton.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    attackBrandBurnsEnemy(state);
  });

  win.addEventListener("click", (event) => {
    event.stopPropagation();
  });

  win.addEventListener("animationend", (event) => {
    if (event.target !== win) return;
    if (event.animationName === "retro-window-open") {
      win.classList.remove("is-opening");
      clampRandomEventWindowToViewport(win);
      return;
    }
    if (event.animationName === "retro-window-close") {
      removeBrandBurnsEnemyWindow(win);
    }
  });

  image.addEventListener("load", () => clampRandomEventWindowToViewport(win));
  updateBrandBurnsEnemyHud(state);
  return state;
};

const chooseBrandBurnsEnemies = () => {
  const apostleCount = Math.max(0, BRAND_BURNS_ENCOUNTER_COUNT - 1);
  const apostles = shuffleBrandBurnsItems(BRAND_BURNS_APOSTLES).slice(0, apostleCount);
  return shuffleBrandBurnsItems([BRAND_BURNS_FEMTO, ...apostles]);
};

const openBrandBurnsEnemyWindow = (state) => {
  if (!state?.win || brandBurnsStage !== "fight") return;
  document.body.appendChild(state.win);
  brandBurnsEnemyWindows.push(state.win);
  state.win.classList.remove("is-hidden", "is-closing");
  state.win.setAttribute("aria-hidden", "false");
  positionRandomEventWindowInViewport(state.win);
  state.win.style.zIndex = String(topZ++);
  restartWindowAnimation(state.win, "is-opening");
  clampRandomEventWindowAfterMediaLoad(state.win);
  updateBrandBurnsAttackButtonStates();
  scheduleBrandBurnsEnemyAttack(state);
};

const spawnBrandBurnsEnemies = () => {
  clearBrandBurnsEnemyTimers();
  const enemyStates = chooseBrandBurnsEnemies().map(createBrandBurnsEnemyWindow);
  brandBurnsStats.total = enemyStates.length;
  updateBrandBurnsHud();

  enemyStates.forEach((state, index) => {
    const timer = setTimeout(
      () => openBrandBurnsEnemyWindow(state),
      index * BRAND_BURNS_APOSTLE_OPEN_DELAY_MS
    );
    brandBurnsEnemyTimers.push(timer);
  });
};

const resetBrandBurnsWindow = () => {
  clearBrandBurnsOmenEffect();
  clearBrandBurnsHealEffect();
  clearBrandBurnsEnemyTimers();
  stopBrandBurnsStaminaRecovery();
  stopBrandBurnsEnemyAttacks();
  brandBurnsEnemyWindows.forEach((win) => win.remove());
  brandBurnsEnemyWindows = [];
  removeBrandBurnsPuckWindow();
  brandBurnsPreserveEnemyWindowsOnMainClose = false;
  brandBurnsPuckHasAppeared = false;
  brandBurnsOutcome = null;
  brandBurnsStage = "prompt";
  clearBrandBurnsBlock();
  resetBrandBurnsStats();
  if (brandBurnsTitle) brandBurnsTitle.textContent = "Your Brand Burns...";
  if (brandBurnsIcon) brandBurnsIcon.dataset.src = BRAND_BURNS_BRAND_ICON;
  if (brandBurnsCombatIcon) brandBurnsCombatIcon.dataset.src = BRAND_BURNS_GUTS_ICON;
  setBrandBurnsViewerImage(BRAND_BURNS_DRAGON_SLAYER_ICON);
  if (brandBurnsStatus) {
    setBrandBurnsStatusText("The apostles are closing in.");
  }
  setBrandBurnsStageHidden(brandBurnsPromptStage, false);
  setBrandBurnsStageHidden(brandBurnsFightStage, true);
  updateBrandBurnsActionButton();
  if (brandBurnsClose) brandBurnsClose.disabled = false;
};

const showBrandBurnsWindow = () => {
  if (!brandBurnsWindow) return;
  if (isBrandBurnsVisible()) {
    if (isBrandBurnsMainWindowVisible()) {
      brandBurnsWindow.style.zIndex = String(topZ++);
      clampRandomEventWindowToViewport(brandBurnsWindow);
    }
    return;
  }
  resetBrandBurnsWindow();
  loadDeferredMedia(brandBurnsWindow);
  brandBurnsWindow.classList.remove("is-hidden", "is-closing");
  brandBurnsWindow.setAttribute("aria-hidden", "false");
  positionRandomEventWindowInViewport(brandBurnsWindow);
  clampRandomEventWindowAfterMediaLoad(brandBurnsWindow);
  brandBurnsWindow.style.zIndex = String(topZ++);
  restartWindowAnimation(brandBurnsWindow, "is-opening");
  scheduleBrandBurnsOmenPulse();
  requestAnimationFrame(() => {
    if (brandBurnsFight) brandBurnsFight.focus();
  });
};

const startBrandBurnsFight = () => {
  if (!brandBurnsWindow || brandBurnsStage !== "prompt") return;
  clearBrandBurnsOmenEffect();
  brandBurnsStage = "fight";
  if (brandBurnsTitle) brandBurnsTitle.textContent = "Struggler";
  setBrandBurnsStageHidden(brandBurnsPromptStage, true);
  setBrandBurnsStageHidden(brandBurnsFightStage, false);
  updateBrandBurnsActionButton();
  if (brandBurnsClose) brandBurnsClose.disabled = true;
  loadDeferredMedia(brandBurnsWindow);
  clampRandomEventWindowAfterMediaLoad(brandBurnsWindow);
  startBrandBurnsStaminaRecovery();
  spawnBrandBurnsEnemies();
};

const closeBrandBurnsWindow = () => {
  if (!brandBurnsWindow && !brandBurnsEnemyWindows.length) return;
  const shouldStaggerEnemyClose =
    brandBurnsStats.health <= 0 && brandBurnsEnemyWindows.some(isBrandBurnsEnemyWindowVisible);
  clearBrandBurnsOmenEffect();
  clearBrandBurnsHealEffect();
  clearBrandBurnsEnemyTimers();
  stopBrandBurnsStaminaRecovery();
  stopBrandBurnsEnemyAttacks();
  clearBrandBurnsBlock();
  closeBrandBurnsPuckWindow();
  brandBurnsStage = "idle";
  brandBurnsPreserveEnemyWindowsOnMainClose = shouldStaggerEnemyClose;
  closeBrandBurnsEnemyWindows({ stagger: shouldStaggerEnemyClose });
  if (!brandBurnsWindow || brandBurnsWindow.classList.contains("is-hidden")) return;
  brandBurnsWindow.setAttribute("aria-hidden", "true");
  restartWindowAnimation(brandBurnsWindow, "is-closing");
};

